// Üretilen dosya: tool/ozgun/uret.py. Doğa · Bitkiler ve ormanlar; Türkiye'nin endemik türleri (orta).
const ozNature2Orta = <(String, String, List<String>, String)>[
  ('Bir öğrenci saksıdaki bitkiyi birkaç gün sulamayı unutuyor ve yaprakların sarktığını görüyor. Bu sarkmanın hücre düzeyindeki en doğrudan nedeni nedir?', 'Kofullar su kaybedince turgor basıncı düşer', ['Kloroplastlar sayıca hızla azalır', 'Hücre duvarındaki selüloz suda çözünür', 'Mitokondriler fotosentezi tamamen durdurur'], 'Su kaybeden hücrelerde kofulun hacmi küçülür, hücre duvarına yapılan baskı azalır ve dokular gevşeyerek sarkar.'),
  ('Tuzlu suya konan taze bir marul yaprağının hücrelerinde zarın hücre duvarından ayrılarak büzülmesi olayına ne ad verilir?', 'Plazmoliz', ['Deplazmoliz', 'Fagositoz', 'Hemoliz'], 'Hipertonik ortamda hücre ozmozla su kaybeder ve sitoplazma çeperden ayrılır; buna plazmoliz denir. Saf suya konunca geri dönmesi deplazmolizdir.'),
  ('Domatesin kırmızı, havucun turuncu rengini veren karotenoit pigmentlerini depolayan plastit türü hangisidir?', 'Kromoplast', ['Lökoplast', 'Amiloplast', 'Kloroplast ve proplastit'], 'Kromoplastlar klorofil dışındaki renk pigmentlerini, özellikle karotenoitleri taşır; olgunlaşan domateste kloroplastlar kromoplasta dönüşür.'),
  ('Patates yumrusu hücrelerinde nişasta tanelerini depolayan renksiz plastitlere ne ad verilir?', 'Amiloplast', ['Kromoplast', 'Peroksizom', 'Glioksizom ve mikrocisimcik'], 'Renksiz plastitlere genel olarak lökoplast denir; nişasta depolayanlar amiloplast adını alır ve patates yumrusunda boldur.'),
  ('Robert Hooke 1665\'te mikroskopla incelediği bir bitkisel malzemede gördüğü küçük odacıklara ilk kez \'hücre\' adını vermiştir. Bu malzeme neydi?', 'Şişe mantarı', ['Soğan zarı', 'Elma kabuğu', 'Yosun yaprağı'], 'Hooke, Micrographia adlı eserinde ölü mantar dokusundaki boş hücre duvarlarını tanımlamış ve onları manastır odacıklarına benzeterek \'cell\' adını vermiştir.'),
  ('Fotosentezin ışığa bağlı tepkimeleri kloroplastın hangi bölümünde gerçekleşir?', 'Tilakoit zarlarında', ['Stroma sıvısında', 'Dış zar ile iç zar arasında', 'Kloroplast DNA\'sında'], 'Klorofil ve elektron taşıma zinciri tilakoit zarlarında bulunur; ışık enerjisi burada ATP ve NADPH\'ye dönüştürülür.'),
  ('Kapalı ve ışıklı bir cam fanusta yalnızca bir bitki ile yanan bir mum bulunuyor; mum, bitkisiz fanusa göre daha uzun süre yanıyor. Bu gözlem en iyi nasıl açıklanır?', 'Bitki fotosentezle fanusa oksijen vermektedir', ['Bitki mumun ürettiği ısıyı soğurmaktadır', 'Bitki havadaki azotu artırmaktadır', 'Bitki ışıkta solunumla karbondioksiti tüketmektedir'], 'Joseph Priestley\'nin deneylerine benzeyen bu düzenekte bitki fotosentezle oksijen üreterek yanmanın sürmesini sağlar.'),
  ('Mısır ve şeker kamışı gibi sıcak bölge bitkilerinde karbondioksiti önce dört karbonlu bir bileşiğe bağlayarak fotosentez verimini artıran yol hangisidir?', 'C4 fotosentezi', ['CAM fotosentezi', 'C3 fotosentezi', 'Kemosentez'], 'C4 bitkileri CO2\'yi önce dört karbonlu bileşiklerde yoğunlaştırır; bu, sıcak ve kurak koşullarda RuBisCO\'nun oksijenle boşa çalışmasını azaltır.'),
  ('Kaktüs ve ananas gibi bitkilerin stomalarını gündüz kapalı tutup gece açması hangi uyumla ilgilidir?', 'CAM metabolizmasıyla su kaybını azaltma', ['Gece daha çok ışık soğurma', 'Polen dağılımını gündüze taşıma', 'Kökten daha hızlı ve daha çok mineral alma'], 'CAM bitkileri karbondioksiti serin gecede alıp organik asit olarak depolar, gündüz stomaları kapalıyken fotosentezde kullanır; böylece terlemeyle su kaybı azalır.'),
  ('Karanlık bir dolapta bir hafta bekletilen bir bitkinin yaprağına iyot testi uygulanıyor ve mavi-siyah renk görülmüyor. Bu sonuç neyi gösterir?', 'Yaprakta depolanmış nişasta tükenmiştir', ['Yaprakta hiç klorofil kalmamıştır', 'Yaprak hücrelerinin tamamı ölmüştür', 'Kullanılan iyot çözeltisi bozulmuş ve etkisini yitirmiştir'], 'İyot nişastayla mavi-siyah renk verir. Işıksız kalan bitki nişastasını solunumda kullanır ve fotosentezle yenisini üretemez.'),
  ('Yaprakların iç kısmında, üst yüzeyin hemen altında sıkı dizilmiş ve en çok kloroplast içeren doku hangisidir?', 'Palizat parankiması', ['Süngerimsi parankima', 'Sklerenkima', 'Kollenkima'], 'Palizat (dik) parankiması uzun, sık dizili hücrelerden oluşur ve ışığı en iyi alan konumda bulunduğu için fotosentezin büyük kısmını gerçekleştirir.'),
  ('Yaprağın alt kısmında hücreleri arasında geniş hava boşlukları bulunan ve gaz alışverişini kolaylaştıran doku hangisidir?', 'Süngerimsi parankima', ['Palizat parankiması', 'Epidermis', 'Ksilem ve floemden oluşan damar'], 'Süngerimsi parankimanın gevşek hücreleri arasındaki boşluklar stomalardan giren gazların hücrelere dağılmasını sağlar.'),
  ('Sabah erken saatlerde bazı otların yaprak uçlarında görülen su damlaları çoğunlukla çiğ değil, bitkinin kendi çıkardığı sudur. Bu olay nasıl adlandırılır?', 'Gutasyon', ['Transpirasyon', 'Plazmoliz', 'İmbibisyon'], 'Gutasyonda kök basıncıyla yukarı itilen su, yaprak kenarlarındaki hidatot adlı açıklıklardan sıvı damlacıklar hâlinde dışarı verilir.'),
  ('Ksilemde suyu taşıyan, olgunlaştığında içi boş, cansız hücrelerden oluşan iki temel eleman hangileridir?', 'Trakeler ve trakeitler', ['Kalburlu borular ve arkadaş hücreleri', 'Palizat ve süngerimsi hücreler', 'Bekçi hücreleri ve epidermis hücreleri'], 'Ksilemin iletim elemanları trakeit ve trakelerdir; olgunlukta protoplazmaları kaybolur ve kalınlaşmış odunsu duvarlar kalır.'),
  ('Floemde kalburlu boru hücrelerinin yanında yer alan ve onların yaşamsal işlevlerini destekleyen çekirdekli hücrelere ne ad verilir?', 'Arkadaş hücreleri', ['Trakeit hücreleri', 'Bekçi hücreleri', 'Kök tüyleri ve emici hücreler'], 'Olgun kalburlu borularda çekirdek bulunmaz; yanlarındaki arkadaş hücreleri bu hücrelerin metabolik ihtiyaçlarını karşılar.'),
  ('Odunsu bitkilerde gövdenin her yıl kalınlaşmasını, yani enine büyümeyi sağlayan meristem hangisidir?', 'Vasküler kambiyum', ['Uç meristem', 'Ara meristem', 'Epidermis ve kütikula'], 'Ksilem ile floem arasında yer alan kambiyum, içe doğru odun (ksilem) ve dışa doğru soymuk (floem) üreterek gövdeyi kalınlaştırır.'),
  ('Kök ucunu toprak içinde ilerlerken sürtünmeye karşı koruyan, başlık şeklindeki yapı hangisidir?', 'Kaliptra', ['Kök tüyü', 'Endodermis', 'Perisikl ve kök kambiyumu'], 'Kaliptra kök ucundaki meristemi örten koruyucu bir başlıktır; dış hücreleri sürekli dökülür ve yenilenir, ayrıca yerçekimini algılamada rol oynar.'),
  ('Mısır bitkisinin gövdesinin alt boğumlarından çıkıp toprağa doğru uzanan ve bitkiyi rüzgâra karşı sağlamlaştıran kökler nasıl adlandırılır?', 'Destek kökleri', ['Emeç kökleri', 'Solunum kökleri', 'Depo kökleri'], 'Mısırda gövdeden çıkan ek (adventif) kökler toprağa girerek bitkiye payanda gibi destek olur; bunlara destek kökleri denir.'),
  ('Bataklık kıyılarında yetişen mangrov ağaçlarında çamurdan yukarı doğru dikilen kök uzantılarının başlıca görevi nedir?', 'Oksijence fakir çamurda havayla gaz alışverişi', ['Tuz depolayarak yaprakları beslemek', 'Böcek yakalayıp azot sağlamak', 'Tohumları suya bırakıp akıntıyla uzaklara taşımak'], 'Pnömatofor adı verilen bu solunum kökleri havaya çıkarak su altında kalan köklerin oksijen almasına yardım eder.'),
  ('Patates yumrusu üzerinde bulunan \'gözler\' ondan filiz çıkabilmesini sağlar. Bu gözlerin varlığı patates yumrusunun hangi organ türü olduğunu gösterir?', 'Toprak altı gövdesi', ['Kök', 'Yaprak', 'Meyve ya da tohum'], 'Patatesteki gözler aslında tomurcuklardır; tomurcuk taşıması yumrunun kök değil, değişime uğramış bir gövde olduğunu gösterir.'),
  ('Soğanın yemek olarak tüketilen etli katmanları botanik açıdan neyin değişikliğe uğramış hâlidir?', 'Yaprakların', ['Köklerin', 'Meyvenin', 'Çiçek sapının'], 'Soğan, kısa ve basık bir gövde üzerinde besin depolayan etli yapraklardan oluşur; yediğimiz katmanlar bu depo yapraklarıdır.'),
  ('Çilek bitkisinin toprak yüzeyinde yatay uzanıp belli aralıklarla kök salarak yeni bitkiler oluşturan uzantılarına ne ad verilir?', 'Stolon', ['Rizom', 'Yumru', 'Sülük ya da sarılıcı dal'], 'Stolonlar toprak üstünde yatay uzanan ince gövdelerdir; boğumlarında kök ve yaprak oluşturup yeni bireyler meydana getirir.'),
  ('Zencefil ve süsen bitkilerinde toprak altında yatay uzanan, boğumlu ve besin depolayan gövdeye ne ad verilir?', 'Rizom', ['Stolon', 'Kormus', 'Pnömatofor'], 'Rizom toprak altında yatay büyüyen bir gövdedir; boğumlarından kök ve sürgün verir. Zencefilin baharat olarak kullanılan kısmı rizomdur.'),
  ('Kuraklık stresine giren bir bitkide stomaların kapanmasını tetikleyen başlıca hormon hangisidir?', 'Absisik asit', ['Giberellin', 'Sitokinin', 'Oksin ve etilen birlikte'], 'Absisik asit (ABA) su sıkıntısında yapraklarda birikir ve bekçi hücrelerinin su kaybetmesine yol açarak stomaları kapatır.'),
  ('Karada yaşayan birçok bitkide stomaların yaprağın alt yüzeyinde daha yoğun bulunmasının en akla yatkın yararı nedir?', 'Güneşten korunarak su kaybını azaltır', ['Yağmur suyunun içeri girmesini kolaylaştırır', 'Köklerden gelen suyu doğrudan dışarı atar', 'Polenlerin yapraklara yapışmasını sağlar'], 'Alt yüzey doğrudan güneş almadığı için daha serindir; stomaların burada toplanması terlemeyle su kaybını sınırlar.'),
  ('Su yüzeyinde yüzen nilüfer yapraklarında stomaların çoğunlukla hangi yüzeyde bulunması beklenir?', 'Üst yüzeyde', ['Alt yüzeyde', 'Yaprak sapında', 'Damarların içinde'], 'Yüzen yaprakların alt yüzü suya değdiği için gaz alışverişi yapamaz; bu nedenle stomalar havaya bakan üst yüzeyde toplanır.'),
  ('Mısırda püskül kısmı erkek, koçan kısmı dişi çiçeklerden oluşur ve her ikisi aynı bitkide bulunur. Bu durum nasıl adlandırılır?', 'Bir evcikli (monoik) bitki', ['İki evcikli (dioik) bitki', 'Erselik çiçekli bitki', 'Kendine uyuşmaz ve kısır bitki'], 'Erkek ve dişi çiçekleri ayrı olup aynı birey üzerinde bulunan bitkilere bir evcikli denir; mısır ve fındık örnektir.'),
  ('Bir bahçeye yalnızca tek bir kivi fidanı dikilmiş ve fidan her yıl bolca çiçek açtığı hâlde hiç meyve vermemiştir. Bunun en olası açıklaması nedir?', 'Kivi iki evciklidir ve fidan erkek bireydir', ['Kivi yalnızca tohumla değil sporla da çoğalır', 'Kivi çiçekleri gündüz hiç açmaz', 'Kivinin meyvesi toprak altında gelişir'], 'Kivide erkek ve dişi çiçekler ayrı bireylerdedir. Meyve için dişi bitki ve tozlaştırıcı bir erkek bitki birlikte gerekir.'),
  ('Papatya ya da ayçiçeğinde tek bir çiçek gibi görünen yapı aslında nedir?', 'Çok sayıda küçük çiçeğin oluşturduğu bir baş', ['Taç yaprakları çoğalmış tek bir çiçek', 'Değişime uğramış bir yaprak demeti', 'Tohumları dışarıda duran tek bir büyük meyve'], 'Papatyagillerde yüzlerce küçük çiçek tabla üzerinde toplanarak kapitulum adı verilen ve tek çiçeğe benzeyen bir çiçek durumu oluşturur.'),
  ('Rüzgârla tozlaşan bitkilerin çiçeklerinde genellikle hangi özellik görülür?', 'Gösterişsiz çiçek, bol ve hafif polen', ['Parlak renkli taç yaprak ve güçlü koku', 'Bol nektar ve yapışkan iri polen', 'Gece açan beyaz ve kokulu çiçek'], 'Rüzgârla tozlaşanlar (buğdaygiller, çam, fındık) hayvanları çekmek zorunda olmadığından renk ve koku yerine çok sayıda hafif polen üretir.'),
  ('Arılar insan gözünün göremediği morötesi ışığı algılar. Birçok çiçeğin taç yapraklarında yalnızca morötesi ışıkta görünen desenlerin bulunmasının işlevi nedir?', 'Arıları nektara yönlendirmek', ['Çiçeği yapraklardan serin tutmak', 'Polenleri güneşten korumak', 'Rüzgârla tozlaşmayı kolaylaştırmak'], 'Nektar rehberi denen bu desenler tozlaştırıcıları çiçeğin ortasına yönlendirir ve arının polenle temasını artırır.'),
  ('Bir bitkinin kendi polenleriyle döllenmesini engelleyen \'kendine uyuşmazlık\' mekanizmasının türe başlıca yararı nedir?', 'Genetik çeşitliliği artırması', ['Tohum sayısını sınırsızca artırması', 'Çiçeklerin daha uzun açık kalması', 'Polen üretimini gereksiz kılması'], 'Kendine uyuşmazlık çapraz tozlaşmayı zorunlu kılar; farklı bireylerin genleri karışır ve döller daha çeşitli olur.'),
  ('Kapalı tohumlularda polen tüpünden gelen iki spermden biri yumurtayı döller, diğeri iki kutup çekirdeğiyle birleşir. Bu olaya ne ad verilir?', 'Çift döllenme', ['Partenogenez', 'Tomurcuklanma', 'Rejenerasyon ve klonlama'], 'Çift döllenmede birinci birleşmeden zigot (2n), ikinci birleşmeden besin dokusu olan endosperm (3n) oluşur.'),
  ('Kapalı tohumlularda çift döllenmeyle oluşan endosperm dokusunun kromozom takımı sayısı nedir?', '3n', ['n', '2n', '4n'], 'Endosperm, bir sperm (n) ile iki kutup çekirdeğinin (n + n) birleşmesinden oluştuğu için triploittir.'),
  ('Buğday tanesinde un elde edilen, nişastaca zengin besin dokusu hangisidir?', 'Endosperm', ['Embriyo', 'Kepek', 'Kotiledon kabuğu'], 'Buğday tanesinin büyük bölümü nişastalı endospermden oluşur; beyaz un buradan elde edilir, kepek ise dış örtüdür.'),
  ('Elmanın yediğimiz etli kısmı yumurtalıktan değil, büyük ölçüde çiçek tablasından gelişir. Bu nedenle elma botanikte nasıl bir meyve olarak sınıflandırılır?', 'Yalancı meyve', ['Kuru meyve', 'Bileşik meyve', 'Sert çekirdekli gerçek meyve'], 'Meyvenin etli kısmı yumurtalık dışındaki çiçek parçalarından oluşuyorsa yalancı meyve denir; elma, armut ve ayva bu gruptadır.'),
  ('Dut ve ananas, birçok çiçeğin meyvelerinin bir araya gelip kaynaşmasıyla oluşur. Bu tür meyvelere ne ad verilir?', 'Bileşik meyve', ['Toplu meyve', 'Kuru meyve', 'Yalancı meyve ya da çiçek tablası'], 'Bir çiçek durumundaki pek çok çiçeğin meyveleri birleşerek tek bir yapı oluşturursa buna bileşik meyve denir.'),
  ('Akçaağaç meyvelerinin kanat biçiminde olması ve düşerken pervane gibi dönmesi tohuma hangi yararı sağlar?', 'Düşüşü yavaşlatıp rüzgârla uzağa gitmesini', ['Toprağa daha derin gömülmesini', 'Hayvanların meyveyi yemesini', 'Su üzerinde batmadan uzun süre yüzmesini'], 'Kanatlı meyveler dönerek havada daha uzun kalır; bu sürede rüzgâr onları ana ağaçtan uzaklaştırır.'),
  ('İsviçreli mühendis George de Mestral, köpeğinin tüylerine yapışan çengelli meyvelerden esinlenerek cırt cırt bantı geliştirmiştir. Bu meyveler hangi yayılma yolunun örneğidir?', 'Hayvan tüylerine tutunarak yayılma', ['Rüzgârla uçarak yayılma', 'Su akıntısıyla yayılma', 'Olgun meyvenin patlayarak tohum fırlatması'], 'Dulavratotu gibi bitkilerin meyveleri küçük çengellerle hayvan tüylerine tutunur ve hayvan dolaştıkça uzaklara taşınır.'),
  ('Eşek hıyarı olarak bilinen bitkinin olgun meyvesine dokunulduğunda tohumlar sıvıyla birlikte metrelerce öteye fırlar. Bu bir yayılma yolu olarak nasıl adlandırılır?', 'Kendi kendine (mekanik) yayılma', ['Rüzgârla yayılma', 'Karıncalarla yayılma', 'Suyla ve akıntılarla taşınarak yayılma'], 'Ecballium elaterium meyvesinde iç basınç birikir; meyve saptan kopunca tohumlar fışkırarak fırlatılır.'),
  ('Kuru bir fasulye tohumu suya konduğunda kabuğunu yırtabilecek kadar şişer. Kuru tohumun suyu bu şekilde emmesine ne ad verilir?', 'İmbibisyon', ['Plazmoliz', 'Gutasyon', 'Transpirasyon'], 'İmbibisyon, kuru hücre duvarları ve nişasta gibi maddelerin suyu çekerek şişmesidir; çimlenmenin ilk aşamasıdır.'),
  ('Islak pamuk üzerine konan tohumlar hava almayan, tamamen suyla dolu bir kapta çimlenmiyor. Bunun en olası nedeni nedir?', 'Embriyonun solunum için oksijen bulamaması', ['Suyun tohum kabuğunu çözmesi', 'Işığın suyun içinden geçememesi', 'Suyun tohumu fazla ısıtarak embriyoyu pişirmesi'], 'Çimlenen embriyo enerji için yoğun solunum yapar; su altında oksijen yetersiz kaldığından çimlenme gerçekleşmez.'),
  ('Bazı tohumlar soğuk ve nemli bir kış dönemi geçirmeden çimlenmez. Bu özellik bitkiye nasıl bir yarar sağlar?', 'Fidenin kış başında çıkıp donmasını önler', ['Tohumların daha hızlı çürümesini sağlar', 'Yaprakların sonbaharda yeşil kalmasını sağlar', 'Köklerin daha kısa olmasını sağlar'], 'Soğuklama gereksinimi tohumun ancak kış geçtikten sonra, ilkbaharda çimlenmesini garanti ederek fidenin hayatta kalma şansını artırır.'),
  ('Bir bitkinin tepe tomurcuğu kesildiğinde yan dalların hızla gelişmesi hangi olgunun ortadan kalkmasıyla açıklanır?', 'Tepe baskınlığının', ['Fotoperiyodizmin', 'Vernalizasyonun', 'Gutasyonun ve kök basıncının'], 'Tepe tomurcuğunun ürettiği oksin yan tomurcukların büyümesini baskılar. Uç kesilince bu baskı kalkar ve bitki dallanır; budamada bundan yararlanılır.'),
  ('Çekirdeksiz üzüm üretiminde salkımların daha iri ve taneleri daha büyük olması için bağcılar hangi hormonu uygular?', 'Giberellin', ['Absisik asit', 'Etilen', 'Oksin'], 'Giberellinler hücre uzamasını ve meyve büyümesini uyarır; çekirdeksiz üzüm çeşitlerinde sap uzamasını ve tane iriliğini artırmak için kullanılır.'),
  ('Hücre bölünmesini uyaran ve koparılmış yaprakların sararmasını geciktirdiği bilinen hormon grubu hangisidir?', 'Sitokininler', ['Absisik asitler', 'Etilen', 'Giberellinler'], 'Sitokininler hücre bölünmesini artırır ve yaşlanmayı geciktirir; doku kültüründe oksinle birlikte sürgün oluşumunu yönlendirmek için kullanılır.'),
  ('Çelikle çoğaltmada, kesilen dal parçalarının ucunun köklendirme tozuna batırılması kök oluşumunu kolaylaştırır. Bu tozların etkin maddesi genellikle hangi hormon grubundandır?', 'Oksinler', ['Absisik asitler', 'Etilen', 'Sitokininler'], 'Köklendirme tozları sentetik oksinler içerir; oksinler gövde dokusunda adventif kök oluşumunu uyarır.'),
  ('Bezelye sülüklerinin bir desteğe değdikten sonra onun etrafına sarılması hangi tür hareketin örneğidir?', 'Tigmotropizma', ['Fototropizma', 'Hidrotropizma', 'Termonasti ve fotonasti'], 'Tigmotropizma dokunma uyartısına yönelimli büyüme tepkisidir; dokunulan tarafın hücreleri daha yavaş uzadığı için sülük desteğe sarılır.'),
  ('Küstüm otuna dokunulduğunda yaprakçıkların saniyeler içinde kapanması, yönü uyartının geldiği yere bağlı olmayan bir harekettir. Bu hareketin adı nedir?', 'Sismonasti', ['Fototropizma', 'Kemotropizma', 'Hidrotropizma'], 'Sarsıntı ve dokunmayla tetiklenen yönsüz hareketlere sismonasti denir; yaprak tabanındaki hücrelerin hızla su kaybetmesiyle olur.'),
  ('Lale çiçeklerinin sıcak bir odaya getirildiğinde açılıp serinde kapanması nasıl bir harekettir?', 'Termonasti', ['Tigmotropizma', 'Fotoperiyodizm', 'Gravitropizma'], 'Sıcaklık değişimine bağlı yönsüz açılma-kapanma hareketleri termonasti olarak adlandırılır.'),
  ('Tropizma ile nasti arasındaki temel fark aşağıdakilerden hangisidir?', 'Tropizmada hareket uyartının yönüne bağlıdır', ['Nastide hareket yalnızca köklerde görülür', 'Tropizma yalnızca hayvanlarda görülür', 'Nasti her zaman kalıcı ve geri dönüşsüz büyümeyle olur'], 'Tropizmalar uyartının yönüne göre yönelimli büyüme tepkileridir; nastiler ise uyartının yönünden bağımsız hareketlerdir.'),
  ('Kışlık buğday sonbaharda ekilir ve ancak kışın soğuğunu geçirdikten sonra başak verir. Çiçeklenme için gereken bu soğuk dönemine ne ad verilir?', 'Vernalizasyon', ['Fotoperiyodizm', 'Stratifikasyon', 'Dormansi kırılması'], 'Vernalizasyon, bazı bitkilerin çiçeklenmeye geçebilmesi için bir süre düşük sıcaklığa maruz kalma gereksinimidir.'),
  ('Bitkilerde klorofil molekülünün merkezinde bulunan metal element hangisidir?', 'Magnezyum', ['Demir', 'Kalsiyum', 'Çinko ve bakır'], 'Klorofilin porfirin halkasının merkezinde bir magnezyum atomu bulunur; magnezyum eksikliği yaprak damarları arasında sararmaya yol açar.'),
  ('Baklagillerin köklerindeki nodüllerde yaşayan Rhizobium bakterileri bitkiye hangi katkıyı sağlar?', 'Havadaki azotu bitkinin kullanabileceği hâle getirir', ['Topraktaki tuzu süzerek temizler', 'Bitkinin yerine fotosentez yapar', 'Köklere zararlı mantarları getirip besin alımını engeller'], 'Rhizobium atmosferdeki N2\'yi amonyağa dönüştürür; karşılığında bitkiden şeker alır. Bu ortak yaşam nedeniyle baklagiller toprağı azotça zenginleştirir.'),
  ('Bir çiftçi buğday hasadından sonra aynı tarlaya bir yıl nohut ya da mercimek ekiyor. Bu ekim nöbetinin toprağa başlıca yararı nedir?', 'Toprağın azotça zenginleşmesi', ['Toprağın tuzluluğunun artması', 'Toprağın asitliğinin artması', 'Toprağın kalıcı olarak nemlenmesi'], 'Baklagiller köklerindeki bakteriler sayesinde azot bağlar; kök ve bitki artıkları toprağa karışınca sonraki ürün için azot sağlanmış olur.'),
  ('Sonbaharda bazı ağaçların yapraklarının sararmasının asıl nedeni nedir?', 'Klorofil yıkılınca karotenoitler görünür hâle gelir', ['Yapraklarda sarı renkli yeni su birikir', 'Güneş ışığı yaprakları ağartır', 'Ağaçlar köklerinden yapraklarına sarı kükürt pompalar'], 'Karotenoitler yaz boyunca yaprakta vardır ama klorofil onları gölgeler. Sonbaharda klorofil yıkılınca sarı ve turuncu renkler ortaya çıkar.'),
  ('Sonbaharda bazı akçaağaç ve sumak yapraklarında görülen parlak kırmızı rengi veren pigment grubu hangisidir?', 'Antosiyaninler', ['Klorofiller', 'Karotenler', 'Ksantofiller ve fikobilinler'], 'Kırmızı ve mor renkler çoğunlukla sonbaharda yeni üretilen antosiyaninlerden kaynaklanır; bu pigmentler hücre kofulunda bulunur.'),
  ('Kırmızı lahana suyu sirke eklenince pembeye, karbonat eklenince yeşilimsi maviye döner. Bu renk değişiminden sorumlu pigment hangisidir?', 'Antosiyanin', ['Klorofil', 'Karoten', 'Likopen ve beta-karoten'], 'Antosiyaninler ortamın asitliğine göre renk değiştirir; bu nedenle kırmızı lahana suyu doğal bir pH belirteci olarak kullanılır.'),
  ('Domatesin kırmızı rengini veren karotenoit pigmenti hangisidir?', 'Likopen', ['Klorofil a', 'Antosiyanin', 'Betalain'], 'Likopen domates ve karpuzun kırmızı rengini veren bir karotenoittir; güçlü bir antioksidan olarak da bilinir.'),
  ('Ağaçların sonbaharda yapraklarını dökmesinin, ılıman iklimde kışın hayatta kalmaya en önemli katkısı nedir?', 'Donmuş topraktan su alınamazken su kaybını önlemek', ['Köklerin daha çok ışık almasını sağlamak', 'Gövdenin yaprak yerine fotosentez yapmasını sağlamak', 'Tohumların daha hızlı olgunlaşmasını sağlamak'], 'Kışın toprak suyu donabilir ve kökler su alamaz; geniş yapraklar terlemeye devam etseydi ağaç kururdu. Yaprak dökümü bu kaybı önler ve kar yükünden korur.'),
  ('Karayosunlarının genellikle birkaç santimetreden uzun olamamasının temel nedeni nedir?', 'İletim demetleri yoktur', ['Fotosentez yapamazlar', 'Hücreleri hücre duvarı taşımaz', 'Yalnızca çöllerde yaşayabildikleri için'], 'Yosunlarda ksilem ve floem bulunmaz; su ve madde hücreden hücreye yavaşça geçtiği için boyları kısa kalır ve nemli ortamlara bağlıdırlar.'),
  ('Karayosunlarını toprağa tutturan ama gerçek kök sayılmayan ince ipliksi yapılar hangileridir?', 'Rizoitler', ['Kök tüyleri', 'Sülükler', 'Pnömatoforlar ve hava kökleri'], 'Rizoitler tutunma işlevi görür; iletim dokusu taşımadıkları için gerçek kök değildir.'),
  ('Karayosunlarında döllenme için suya ihtiyaç duyulmasının nedeni nedir?', 'Spermler yumurtaya yüzerek ulaşır', ['Polenleri suyla şişer', 'Tohumları ancak suda çimlenir', 'Sporları yalnızca su altında oluşur'], 'Yosunların kamçılı spermleri yumurtaya ulaşmak için yağmur suyu ya da çiy gibi bir su filmine gereksinim duyar.'),
  ('Bugün çıkarılan taş kömürü yataklarının büyük kısmı, yaklaşık 300 milyon yıl önceki bataklık ormanlarında yaşamış hangi bitkilerin kalıntılarından oluşmuştur?', 'Ağaç boyutlu eğreltiler ve akrabaları', ['Kapalı tohumlu meşe ve kayınlar', 'Kaktüsler ve diğer etli bitkiler', 'Buğdaygiller ve çayırları oluşturan diğer otlar'], 'Karbonifer döneminde dev eğreltiler, pullu ağaçlar ve dev at kuyrukları geniş bataklık ormanları oluşturmuş, kalıntıları zamanla kömüre dönüşmüştür.'),
  ('\'Yaşayan fosil\' olarak anılan, yelpaze biçimli yaprakları olan ve yakın akrabası günümüze ulaşmamış açık tohumlu ağaç hangisidir?', 'Ginkgo biloba', ['Sequoia sempervirens', 'Pinus brutia', 'Taxus baccata'], 'Ginkgo, milyonlarca yıl öncesinden fosilleri bilinen bir grubun yaşayan tek türüdür; yelpaze yaprakları ve iki evcikli yapısıyla tanınır.'),
  ('Kapalı tohumlu bitkileri diğer bütün bitki gruplarından ayıran özellikler hangi seçenekte birlikte verilmiştir?', 'Çiçek ve meyve oluşturmaları', ['Spor ve rizoit taşımaları', 'İletim dokusu ve kök taşımaları', 'Kozalak ve iğne yaprak taşımaları'], 'Gerçek çiçek ve tohumu saran meyve yalnızca kapalı tohumlularda bulunur; iletim dokusu eğreltilerde ve açık tohumlularda da vardır.'),
  ('Aşağıdaki özelliklerden hangisi çift çenekli bitkilere özgüdür?', 'Çiçek parçalarının genellikle dört ya da beşin katı olması', ['Yapraklarda paralel damarlanma', 'Saçak kök sistemi', 'Gövdede iletim demetlerinin dağınık ve düzensiz yerleşmesi'], 'Çift çeneklilerde çiçek parçaları genellikle 4 ya da 5\'in katıdır; diğer seçenekler tek çeneklilerin tipik özellikleridir.'),
  ('Bir bitki kesitinde iletim demetlerinin gövdede halka şeklinde dizildiği görülüyor. Bu bitki için en olası grup hangisidir?', 'Çift çenekli', ['Tek çenekli', 'Karayosunu', 'Ciğer otu ya da boynuzlu yosun'], 'Çift çeneklilerde iletim demetleri halka şeklinde dizilir ve aralarında kambiyum bulunur; tek çeneklilerde ise demetler gövdeye dağınık yayılmıştır.'),
  ('Aşağıdaki bitki çiftlerinden hangisinde ikisi de tek çeneklidir?', 'Buğday ve orkide', ['Mısır ve meşe', 'Pirinç ve domates', 'Soğan ve elma'], 'Buğday (buğdaygiller) ve orkide (orkidegiller) tek çeneklidir; meşe, domates ve elma çift çeneklidir.'),
  ('Kara bitkilerinin evrimsel olarak hangi canlı grubundan türediği kabul edilir?', 'Yeşil alglerden', ['Kırmızı alglerden', 'Mantarlardan', 'Siyanobakterilerden doğrudan'], 'Klorofil a ve b, nişasta depolama ve selüloz duvar gibi ortak özellikler kara bitkilerinin tatlı su yeşil alglerinden, özellikle karofitlerden türediğini gösterir.'),
  ('Likenler genellikle ayrı bir bitki gibi düşünülse de aslında iki canlının ortak yaşamıdır. Bu iki ortak hangileridir?', 'Bir mantar ile bir alg ya da siyanobakteri', ['Bir yosun ile bir eğrelti', 'Bir bakteri ile bir virüs', 'Bir böcek ile ağaç kabuğunda yaşayan bir mantar'], 'Liken, mantarın sağladığı koruma ve su ile alg veya siyanobakterinin fotosentezle ürettiği besinin paylaşıldığı bir ortak yaşamdır.'),
  ('Dünyada kapalı tohumlu bitkilerin içinde en çok türe sahip familyalardan biri olarak bilinen, Türkiye\'de salep yapımında yumruları kullanılan türleri de içeren familya hangisidir?', 'Orkidegiller', ['Gülgiller', 'Turpgiller', 'Kabakgiller ve karpuzgiller'], 'Orkidegiller (Orchidaceae) papatyagillerle birlikte en kalabalık bitki familyalarındandır; Anadolu\'daki bazı orkidelerin yumrularından salep elde edilir.'),
  ('Turpgiller familyasının çiçeklerini tanımada kullanılan ve familyanın eski adına da yansımış özellik nedir?', 'Dört taç yaprağın haç biçiminde dizilmesi', ['Çiçeklerin şemsiye biçiminde toplanması', 'Kelebeğe benzeyen taç yapısı', 'Taç yapraklarının tek bir boru oluşturması'], 'Turpgillere eskiden haçlıgiller (Cruciferae) denirdi; dört taç yaprağı çarpı biçiminde dizilir.'),
  ('Havuç, maydanoz, dereotu, anason ve kimyon aynı familyadandır. Bu familyanın çiçek durumu hangi biçimiyle tanınır?', 'Şemsiye biçimli çiçek durumu', ['Başak biçimli çiçek durumu', 'Tek ve iri bir çiçek', 'Kedicik denen sarkık çiçek durumu'], 'Maydanozgillerin (Apiaceae) küçük çiçekleri sapları tek noktadan çıkan şemsiye (umbella) biçiminde toplanır; eski adı şemsiyegillerdir.'),
  ('Kavun, karpuz, kabak ve hıyar aynı familyadandır. Bu bitkilerin çoğunun büyüme biçimi için hangisi doğrudur?', 'Sülüklerle tırmanan ya da yerde sürünen otsu bitkilerdir', ['Yüksek boylu, odunsu ağaçlardır', 'Su içinde yaşayan, köksüz bitkilerdir', 'Dikenli dalları olan, iğne yapraklı ve herdem yeşil çalılardır'], 'Kabakgiller genellikle tek yıllık, sülüklü ve sürünücü ya da tırmanıcı otsu bitkilerdir.'),
  ('Pamuk, bamya ve ebegümeci aynı familyaya aittir. Bu familya hangisidir?', 'Ebegümecigiller', ['Patlıcangiller', 'Gülgiller', 'Kabakgiller familyası'], 'Ebegümecigiller (Malvaceae) genellikle beş taç yapraklı çiçekleri ve birleşik erkek organ borusuyla tanınır; pamuk, bamya ve ebegümeci bu familyadandır.'),
  ('Ayçiçeğinin dünyaya hangi kıtadan yayıldığı bilinmektedir?', 'Kuzey Amerika', ['Avrupa', 'Avustralya', 'Güneydoğu Asya adaları'], 'Ayçiçeği Kuzey Amerika\'da yerli halklar tarafından kültüre alınmış, Avrupa\'ya 16. yüzyılda götürülmüştür.'),
  ('Lale, sümbül ve nergis gibi soğanlı bitkilerin çiçek parçaları genellikle kaçar kaçar dizilir?', 'Üçer ya da üçün katları hâlinde', ['Dörder ya da dördün katları hâlinde', 'Beşer ya da beşin katları hâlinde', 'Yedişer ve yedinin katları hâlinde'], 'Bu bitkiler tek çeneklidir; tek çeneklilerde çiçek parçaları genellikle üç ya da üçün katlarıdır. Lalede altı periant parçası ve altı erkek organ bulunur.'),
  ('Yeşil kalmış ya da ışıkta yeşillenmiş patates yumrularının yenmemesi önerilir. Bunun nedeni nedir?', 'Zehirli solanin miktarının artması', ['Nişastanın tamamen şekere dönüşmesi', 'Yumruya küf mantarı yerleşmesi', 'Yumrunun suyunu tamamen kaybetmesi'], 'Işık patateste klorofil ile birlikte solanin alkaloidinin üretimini artırır; solanin fazla alındığında zehirlenmeye yol açar.'),
  ('Isırgan otuna dokunulduğunda deride oluşan yanma hissinin kaynağı nedir?', 'Kırılgan uçlu tüylerin deriye kimyasal madde enjekte etmesi', ['Yaprakların yüksek sıcaklıkta olması', 'Bitkinin elektrik akımı üretmesi', 'Köklerden çıkan zehirli gazın deriye yerleşip yakması'], 'Isırganın silika uçlu iğne tüyleri deriye değince kırılır ve içindeki histamin, asetilkolin ve formik asit gibi maddeler deriye geçer.'),
  ('Zakkum, Akdeniz kıyılarında yol kenarlarında süs bitkisi olarak sık dikilir. Bu bitkiyle ilgili hangi bilgi doğrudur?', 'Bütün kısımları kalbi etkileyen zehirler içerir', ['Yaprakları çay olarak güvenle içilir', 'Yalnızca çiçekleri zehirlidir, diğer kısımları zararsızdır', 'Meyveleri sağlıklı ve tatlı olduğu için pazarda satılır'], 'Zakkum (Nerium oleander) kalp glikozitleri içerir; yaprak, çiçek ve dalları dahil her parçası zehirlidir.'),
  ('Bir meyve çeşidini tohumla değil de aşıyla çoğaltmanın başlıca nedeni nedir?', 'Elde edilen ağacın ana ağaçla aynı özellikleri taşıması', ['Tohumla çoğalan ağaçların hiç meyve vermemesi', 'Aşının ağacın yaşam süresini sınırsız uzatması', 'Tohumların toprakta hiçbir zaman çimlenmemesi ve çürümesi'], 'Tohumla oluşan bireyler eşeyli üremenin sonucu olarak genetik farklılık gösterir; aşı ise ana ağacın kopyasını üretir ve çeşit özelliklerini korur.'),
  ('Bir asma dalı ana bitkiden ayrılmadan toprağa gömülüyor, kök saldıktan sonra kesilip ayrılıyor. Bu yöntem nasıl adlandırılır?', 'Daldırma', ['Aşılama', 'Doku kültürü', 'Göz aşısı yapma'], 'Daldırmada dal ana bitkiden beslenmeye devam ederken toprak içinde kök oluşturur; köklenince ayrılır.'),
  ('Laboratuvarda bir bitkinin birkaç hücresinden steril besi ortamında binlerce özdeş fide üretilmesine ne ad verilir?', 'Doku kültürü', ['Çapraz tozlaşma', 'Aşılama', 'Tohum ıslahı ve melezleme'], 'Doku kültürüyle hastalıksız ve genetik olarak özdeş çok sayıda bitki kısa sürede elde edilebilir; orkide ve muz üretiminde yaygındır.'),
  ('Böcekçil bitkilerin çoğu bataklık gibi besin bakımından fakir topraklarda yaşar. Bu bitkiler böcekleri sindirerek özellikle hangi elementi sağlar?', 'Azot', ['Oksijen', 'Karbon', 'Hidrojen'], 'Böcekçil bitkiler fotosentez yapar ama topraktan yeterince azot alamaz; yakaladıkları böceklerin proteinlerinden azot elde ederler.'),
  ('Testi bitkilerinde (Nepenthes) yaprağın ucu sindirim sıvısıyla dolu bir testiye dönüşmüştür. Böcekler bu tuzağa en çok hangi şekilde yakalanır?', 'Kaygan ağız kenarından içeri düşerek', ['Yapışkan tüylere yapışarak', 'Hızla kapanan iki yaprak arasında kalarak', 'Emici bir su kesesine çekilerek'], 'Nektarla çekilen böcekler testinin kaygan ağız kenarında kayar ve dibindeki sindirim sıvısına düşer.'),
  ('Klorofil taşımayan, sarı-turuncu ipliksi gövdesiyle başka bitkilere sarılan ve emeçleriyle onların besinini alan bitki hangisidir?', 'Küsküt', ['Ökse otu', 'Sarmaşık', 'Asma'], 'Küsküt (Cuscuta) tam parazittir; yaprakları pul hâlindedir ve fotosentez yapmaz. Emeç (haustorium) denen uzantılarla konağın iletim dokusuna girer.'),
  ('Ökse otu yeşil yaprakları olduğu hâlde yarı parazit olarak sınıflandırılır. Bunun nedeni nedir?', 'Fotosentez yapar ama su ve mineralleri konağından alır', ['Hiç fotosentez yapmaz ve tüm besinini konaktan alır', 'Toprağa kök salar ama gece konağa tutunur', 'Yalnızca böcekleri sindirerek beslenir'], 'Ökse otu (Viscum) kendi şekerini üretebilir; ancak toprağa kök salmaz, su ve mineralleri konak ağacın ksileminden çeker.'),
  ('Dünyanın bilinen en büyük tekil çiçeğini açan, yaprak, gövde ve kökü olmayan ve bir asma türünün içinde parazit yaşayan Güneydoğu Asya bitkisi hangisidir?', 'Rafflesia arnoldii', ['Victoria amazonica', 'Welwitschia mirabilis', 'Amorphophallus titanum'], 'Rafflesia arnoldii\'nin tek bir çiçeği yaklaşık bir metre çapa ulaşabilir; çürük et kokusuyla leş sineklerini çekerek tozlaşır.'),
  ('Kuru ve sıcak bölgelerde yaşayan bitkilerde aşağıdaki uyumlardan hangisi beklenmez?', 'Geniş, ince ve bol stomalı yapraklar', ['Kalın kütikula', 'Derinlere inen kökler', 'Dikene dönüşmüş yapraklar ve etli gövde'], 'Kurak ortam bitkileri su kaybını azaltacak şekilde uyum sağlar; geniş, ince ve bol stomalı yapraklar su kaybını artırdığı için bu bitkilere uygun değildir.'),
  ('Afrika\'nın kurak savanlarında yetişen baobab ağacının çok kalın gövdesi kurak mevsimde hayatta kalmasına nasıl katkı sağlar?', 'Büyük miktarda su depolar', ['Yoğun bir yaprak örtüsünü sürekli taşır', 'Gövdesinde böcekleri sindirir', 'Toprak altında yumru oluşturur'], 'Baobabın süngerimsi odunu yağışlı mevsimde çok miktarda su biriktirir; ağaç kurak mevsimde yapraklarını dökerek bu suyla yaşar.'),
  ('Su altında yaşayan bitkilerin gövde ve yapraklarında hücreler arasında geniş hava kanalları bulunur. Bu dokunun bitkiye başlıca yararı nedir?', 'Hem yüzmeyi kolaylaştırır hem oksijen taşır', ['Bitkiyi tuzdan korur', 'Köklerin toprağa daha sıkı tutunmasını sağlar', 'Fotosentezi tamamen gereksiz kılar'], 'Aerenkima denen bu doku su altındaki organlara hava ileterek solunumu destekler ve bitkiye kaldırma kuvveti kazandırır.'),
  ('Nilüfer (lotus) yapraklarının üzerine düşen su damlacıkları yaprağı ıslatmadan yuvarlanıp kiri de alıp götürür. Bu özellikten esinlenerek geliştirilen kendi kendini temizleyen yüzeylere ne ad verilir?', 'Lotus etkisi', ['Kılcallık etkisi', 'Sera etkisi', 'Doppler etkisi'], 'Lotus yaprağının yüzeyindeki mikroskobik çıkıntılar ve mum kristalleri suyu iter; boya, cam ve kumaş teknolojilerinde bu ilke taklit edilmiştir.'),
  ('Amazon havzasında yaşayan ve kenarları yukarı kıvrık yaprakları iki metreyi aşabilen dev nilüfer türü hangisidir?', 'Victoria amazonica', ['Nelumbo nucifera', 'Welwitschia mirabilis', 'Rafflesia arnoldii'], 'Victoria amazonica\'nın yüzen yaprakları alt yüzündeki kalın damarlarla desteklenir ve küçük bir çocuğu taşıyabilecek kadar dayanıklıdır.'),
  ('Kızılçam kozalaklarının bir kısmı ağaç üzerinde yıllarca kapalı kalır ve yangının sıcaklığıyla açılarak tohum döker. Bu özellik türe nasıl bir yarar sağlar?', 'Yangından sonra alanın hızla yeniden ormanlaşmasını', ['Ağacın yangında hiç yanmamasını', 'Tohumların kuşlarca daha kolay yenmesini', 'Kozalağın daha hafif olup rüzgârla kilometrelerce uçmasını'], 'Yangında yetişkin ağaçlar zarar görse de açılan kozalaklardan dökülen tohumlar küllü, ışıklı toprakta çimlenir; kızılçam ormanları bu sayede yenilenir.'),
  ('Sarıkamış ormanlarıyla özdeşleşmiş, gövdesinin üst kısmındaki turuncu-sarı kabuğuyla tanınan ve Türkiye\'de çoğunlukla Kuzeydoğu Anadolu\'da yaygın olan çam türü hangisidir?', 'Sarıçam', ['Kızılçam', 'Halep çamı', 'Fıstık çamı'], 'Sarıçam (Pinus sylvestris) soğuğa çok dayanıklıdır; Avrasya\'nın kuzeyinde geniş alanlara yayılır, Türkiye\'de özellikle Sarıkamış ve Doğu Karadeniz\'in iç kesimlerinde ormanlar kurar.'),
  ('İç Anadolu\'ya bakan dağ yamaçlarında ve Kütahya, Eskişehir çevresinde geniş ormanlar oluşturan, koyu renkli kabuğu ve sert, uzun iğneleriyle tanınan çam türü hangisidir?', 'Karaçam', ['Kızılçam', 'Sarıçam', 'Fıstık çamı'], 'Karaçam (Pinus nigra) karasal iklim koşullarına dayanıklıdır; Türkiye\'de geniş yayılış gösterir ve değerli bir kereste ağacıdır.'),
  ('Çam türlerini ayırt etmede kullanılan bir özellik, iğnelerin kısa bir sürgün üzerinde demetler hâlinde bulunmasıdır. Kızılçam ve karaçamda bir demette genellikle kaç iğne bulunur?', '2', ['5', '1', '3'], 'Kızılçam, karaçam, sarıçam ve fıstık çamı iki iğneli çamlardandır; beş iğneli çamlar ise ayrı bir gruptur.'),
  ('Toros Dağları\'nda yüksek kesimlerde ormanlar oluşturan, Lübnan bayrağında da yer alan ve yatay katlar hâlinde uzanan dallarıyla tanınan ağaç hangisidir?', 'Toros sediri (Cedrus libani)', ['Toros göknarı (Abies cilicica)', 'Doğu ladini (Picea orientalis)', 'Uludağ göknarı (Abies bornmuelleriana)'], 'Cedrus libani\'nin Türkiye\'deki en geniş yayılışı Toroslardadır; ağaç Lübnan\'ın ulusal simgesidir. Dayanıklı ve kokulu odunu eski çağlardan beri değerlidir.'),
  ('Doğu Karadeniz\'in nemli dağ yamaçlarında koyu yeşil ormanlar kuran, kısa iğneli ve sarkık kozalaklı ağaç hangisidir?', 'Doğu ladini', ['Kızılçam', 'Fıstık çamı', 'Halep çamı ya da sarıçam'], 'Doğu ladini (Picea orientalis) Türkiye\'de başta Artvin ve Rize olmak üzere Doğu Karadeniz\'de yayılır; doğal alanı Kafkasya\'ya uzanır.'),
  ('Porsuk ağacı (Taxus baccata) hakkında aşağıdakilerden hangisi doğrudur?', 'Kırmızı etli örtü dışındaki kısımları zehirlidir', ['Kozalakları iri ve odunsudur', 'Yapraklarını her sonbahar döker', 'Meyveleri tatlıdır ve bütün kısımları tamamen zararsızdır'], 'Porsuğun tohumu kırmızı, etli bir örtüyle (aril) sarılıdır; aril dışında yaprak, odun ve tohum taksin alkaloitleri içerir ve zehirlidir.'),
  ('Ardıçların meyveye benzeyen mavi-mor yapıları botanik açıdan nedir?', 'Etlenmiş kozalak', ['Gerçek üzümsü meyve', 'Kurutulmuş çiçek', 'Yaprak gallesi'], 'Ardıç açık tohumludur; pulları etlenip kaynaşan küçük kozalakları meyveye benzer. Cinin kendine özgü aroması bu kozalaklardan gelir.'),
  ('Dünyada en uzun boylu ağaç türü olarak bilinen ve doğal yayılışı Kaliforniya ile Oregon kıyı sisli ormanlarında olan ağaç hangisidir?', 'Kıyı sekoyası (Sequoia sempervirens)', ['Dev sekoya (Sequoiadendron giganteum)', 'Kızılçam (Pinus brutia)', 'Avustralya okaliptüsü (Eucalyptus regnans)'], 'Kıyı sekoyaları 100 metreyi aşan boylara ulaşabilen en uzun ağaç türüdür; dev sekoya ise gövde hacmi bakımından en büyük ağaçtır.'),
  ('Türkiye\'de doğal yayılış gösteren göknar türleri arasında Batı Karadeniz dağlarında, örneğin Uludağ, Bolu ve Kastamonu çevresinde yayılan alt tür hangisidir?', 'Uludağ göknarı', ['Kazdağı göknarı', 'Toros göknarı', 'Doğu Karadeniz göknarı'], 'Uludağ göknarı (Abies nordmanniana subsp. bornmuelleriana) Batı Karadeniz dağlarına özgü, Türkiye\'ye endemik bir göknardır.'),
  ('Yalnızca Balıkesir ve Çanakkale arasındaki Kaz Dağları ile çevresinde doğal olarak yetişen, Türkiye\'ye endemik göknar hangisidir?', 'Kazdağı göknarı', ['Toros göknarı', 'Uludağ göknarı', 'Doğu Karadeniz göknarı'], 'Abies nordmanniana subsp. equi-trojani dünyada yalnızca Kaz Dağları yöresinde bulunur; bu yüzden korunması özellikle önemlidir.'),
  ('Kozalaklı ağaçlarda yaralanan gövdeden sızan reçinenin ağaç için başlıca işlevi nedir?', 'Yarayı kapatıp böcek ve mantarlara karşı korumak', ['Fotosentez için ek su sağlamak', 'Tohumları rüzgârla taşımak', 'Kökleri kışın soğuktan ve dondan korumak'], 'Reçine yaralı bölgeyi örter, böcekleri yapıştırır ve içerdiği terpenlerle mantar ve bakterilere karşı kimyasal bir kalkan oluşturur.'),
  ('Çam reçinesinin damıtılmasıyla elde edilen ve boya inceltici olarak kullanılan uçucu sıvı hangisidir?', 'Terebentin', ['Gliserin', 'Kafur', 'Neftalin ya da naftalin'], 'Reçine damıtıldığında uçucu kısım terebentin yağını, geride kalan katı kısım ise kolofan (reçine sakızı) adıyla bilinen maddeyi verir.'),
  ('İğne yapraklı ağaçların karlı ve soğuk bölgelerde yaygın olmasına katkı sağlayan özelliklerden biri aşağıdakilerden hangisidir?', 'Koni biçimli tepe yapısıyla karın kayıp düşmesi', ['Kışın yapraklarını tamamen dökmeleri', 'Köklerinin suyu dondurmayı engellemesi', 'Çiçeklerinin kar altında açarak tozlaşması'], 'Koni biçimli tepe ve esnek dallar karın birikmesini azaltarak dal kırılmalarını önler; dar iğneler de su kaybını sınırlar.'),
  ('Sedir ağacının odununun eskiçağlardan beri gemi yapımında ve tapınaklarda tercih edilmesinin nedeni aşağıdakilerden hangisidir?', 'Kokulu, dayanıklı ve çürümeye dirençli olması', ['Çok hafif olup suda erimesi', 'Tamamen esnek olup bükülebilmesi', 'Hiç yanmayan ve ısıyı geçirmeyen yapıda olması'], 'Sedir odunu güzel kokulu, dayanıklı ve böceklere karşı dirençlidir; Mısırlılar ve Fenikeliler bu ağacı kullanmıştır.'),
  ('Karadeniz Bölgesi\'nin nemli ormanlarında en yaygın geniş yapraklı ağaçlardan olan, düz ve gümüşi gri kabuğuyla tanınan ağaç hangisidir?', 'Doğu kayını', ['Kızılçam', 'Saplı meşe', 'Adi servi ya da ardıç'], 'Doğu kayını (Fagus orientalis) Karadeniz ve Marmara\'nın nemli yamaçlarında saf ve karışık ormanlar kurar; kabuğu yaşlansa da genellikle düz kalır.'),
  ('Kabuğunun dış kısmı kalın bir mantar tabakası oluşturan ve şişe tıpası yapımında kullanılan meşe türü hangisidir?', 'Mantar meşesi (Quercus suber)', ['Kasnak meşesi (Quercus vulcanica)', 'Kermes meşesi (Quercus coccifera)', 'Saplı meşe (Quercus robur)'], 'Mantar meşesinin kabuğu ağaca zarar vermeden belirli aralıklarla soyulabilir; elde edilen hafif ve su geçirmez mantar tıpa ve yalıtımda kullanılır.'),
  ('Ağaç gövdelerinin kabuğunda görülen ve dokuların gaz alışverişini sağlayan küçük, kabarık açıklıklara ne ad verilir?', 'Lentisel', ['Stoma', 'Hidatot', 'Plazmodesma'], 'Lentiseller mantar dokusundaki gevşek hücreli bölgelerdir; kalınlaşmış gövdede canlı dokuların oksijen almasını sağlar. Huş ve kiraz kabuğunda belirgindir.'),
  ('Çiçekleri kurutularak çay olarak içilen ve çiçek sapının uzun, dil biçimli yeşil bir yaprakçığa yapışık olmasıyla tanınan ağaç hangisidir?', 'Ihlamur', ['Dişbudak', 'Akçaağaç', 'Kestane'], 'Ihlamur (Tilia) çiçek durumları kanat gibi bir brakteye bağlıdır; bu yapı meyvelerin rüzgârla dönerek yayılmasına da yardım eder.'),
  ('Kuzey Amerika kökenli olup Türkiye\'de yol kenarlarında ve erozyon alanlarında çok dikilen, dikenli dalları ve kokulu beyaz salkım çiçekleriyle tanınan ağaç hangisidir?', 'Yalancı akasya (Robinia pseudoacacia)', ['Mimoza (Acacia dealbata)', 'Erguvan (Cercis siliquastrum)', 'Doğu çınarı (Platanus orientalis)'], 'Halk arasında akasya denen bu ağaç baklagillerdendir; azot bağlaması ve hızlı büyümesi nedeniyle bozuk alanlarda tercih edilmiştir. Gerçek akasyalar ayrı bir cinstir.'),
  ('Avustralya kökenli olup 20. yüzyılda Çukurova\'da bataklıkları kurutmak amacıyla yoğun olarak dikilen hızlı büyüyen ağaç hangisidir?', 'Okaliptüs', ['Kızılçam', 'Doğu kayını', 'Sakallı kavak'], 'Okaliptüsler topraktan çok su çeken hızlı büyüyen ağaçlardır; sıtma ile mücadele kapsamında bataklık alanlarda dikilmişlerdir.'),
  ('İlkbaharın sonunda havada uçuşan beyaz, pamuk benzeri tüyler hangi ağaçların tohumlarına aittir?', 'Kavak ve söğütlerin', ['Çam ve köknarların', 'Meşe ve kayınların', 'Çınar ve ıhlamurların'], 'Kavak ve söğütlerin küçük tohumları uzun ipeksi tüylerle donanmıştır; dişi ağaçlardan saçılan bu tüyler rüzgârla taşınır.'),
  ('Bursa\'nın kestane şekeri ve Karadeniz\'in kestane balı hangi ağaçla ilgilidir?', 'Anadolu kestanesi (Castanea sativa)', ['At kestanesi (Aesculus hippocastanum)', 'Doğu kayını (Fagus orientalis)', 'Türk fındığı (Corylus colurna)'], 'Yenilen kestane Castanea sativa\'nın meyvesidir. At kestanesi farklı bir ailedendir ve tohumları yenmez.'),
  ('Karadeniz\'de yaygın olarak yetiştirilen fındık için hangi bilgi doğrudur?', 'Rüzgârla tozlaşan, bir evcikli bir çalıdır', ['Böceklerle tozlaşan, iki evcikli bir ağaçtır', 'Yalnızca sporla çoğalan bir bitkidir', 'Tropik iklimde yetişen bir palmiyedir'], 'Fındıkta erkek çiçekler kışın sarkan kediciklerde, dişi çiçekler küçük tomurcuklarda aynı bitki üzerinde bulunur; polenler rüzgârla taşınır.'),
  ('Akdeniz ikliminde yetişen zeytin ağacının yaprakları gümüşi alt yüzü ve sert dokusuyla bilinir. Bu yaprak yapısı en çok hangi koşula uyumdur?', 'Sıcak ve kurak yazlarda su kaybını azaltmaya', ['Kışın kar yükünü taşımaya', 'Gölgeli orman tabanında az ışığı yakalamaya', 'Su altında gaz alışverişi yapmaya'], 'Zeytin yapraklarının alt yüzündeki pul tüyler ve kalın kütikula yazın terlemeyi azaltır; bu tip sert yapraklılık Akdeniz bitkilerine özgüdür.'),
  ('Ege ve Akdeniz kıyılarındaki makilerde yetişen, kırmızı ve çilek benzeri yenilebilir meyveleri olan, kışın çiçek açan herdem yeşil çalı ya da küçük ağaç hangisidir?', 'Kocayemiş', ['Kızılcık', 'Alıç', 'Kuşburnu ya da yabani gül'], 'Kocayemiş (Arbutus unedo) makinin tipik türlerindendir; meyvesi bir yıl önceki çiçeklerden olgunlaştığı için çiçek ve meyve ağaçta aynı anda görülebilir.'),
  ('Bir zamanlar geniş bir alana yayılmışken iklim değişiklikleri sonucunda yalnızca küçük alanlarda varlığını sürdürebilen türlere ne ad verilir?', 'Relikt (kalıntı) tür', ['Kozmopolit tür', 'İstilacı tür', 'Melez ve kültür türü'], 'Relikt türler geçmiş jeolojik dönemlerin kalıntılarıdır; Anadolu sığlası gibi Tersiyer kökenli türler bu duruma örnek gösterilir.'),
  ('Bir dağ zirvesinde yetişen bitki türünün çevredeki ovalarda hiç bulunmaması, onun neden endemik olabileceğini açıklar. Bu durumda endemizmi doğuran asıl süreç nedir?', 'Coğrafi yalıtım altında ayrı evrimleşme', ['Türün çok hızlı yayılabilmesi', 'İnsanların türü bilinçli olarak taşıması', 'Türün tüm iklimlere uyum sağlaması'], 'Dağ tepeleri birer \'ada\' gibi davranır; çevreden yalıtılan topluluklar zamanla ayrı evrimleşerek yalnızca o yerde bulunan türlere dönüşebilir.'),
  ('Türkiye\'nin bitki çeşitliliği bakımından dikkat çekici olmasında rol oynayan üç fitocoğrafik bölge hangileridir?', 'Avrupa-Sibirya, Akdeniz ve İran-Turan', ['Tropikal, Arktik ve Antarktik', 'Sahra-Sind, Neotropik ve Avustralya', 'Amazon, Kongo ve Sibirya ormanları bölgeleri'], 'Türkiye\'de Karadeniz kuşağı Avrupa-Sibirya, kıyı kesimleri Akdeniz, iç ve doğu kesimleri İran-Turan bölgesine girer; üç bölgenin buluşması çeşitliliği artırır.'),
  ('Türkiye florasında yer alan endemik bitki taksonlarının oranı için en doğru yaklaşık değer hangisidir?', 'Yaklaşık üçte biri', ['Yaklaşık yirmide biri', 'Yarıdan fazlası', 'Yüzde birden az'], 'Türkiye\'de kayıtlı bitki taksonlarının yaklaşık üçte biri endemiktir; bu oran Avrupa ülkeleriyle karşılaştırıldığında çok yüksektir.'),
  ('Türkiye\'nin yaklaşık 12.000 bitki taksonu barındırdığı ve bunun kabaca tüm Avrupa kıtasındaki bitki sayısına yakın olduğu belirtilir. Bu karşılaştırma en çok neyi vurgular?', 'Türkiye\'nin küçük alanına göre olağanüstü bitki zenginliğini', ['Avrupa\'da bitki türlerinin tamamen yok olduğunu', 'Türkiye\'deki bitkilerin Avrupa\'dan getirildiğini', 'Türkiye\'nin Avrupa\'dan daha büyük bir yüzölçümüne sahip olduğunu'], 'Türkiye\'nin yüzölçümü Avrupa\'nın küçük bir bölümü olduğu hâlde benzer sayıda bitki taksonu barındırması, birim alana düşen çeşitliliğin çok yüksek olduğunu gösterir.'),
  ('Türkiye\'nin buzul çağlarında birçok bitki türü için bir sığınak (refugium) işlevi gördüğü düşünülür. Bunun en önemli nedeni nedir?', 'Kuzey Avrupa kadar buzullarla kaplanmaması', ['Bütünüyle tropikal bir iklime sahip olması', 'Hiç dağ bulunmaması', 'Okyanusların ortasında yalıtılmış bir ada olması'], 'Buzul dönemlerinde Kuzey Avrupa geniş buz örtüleriyle kaplanırken Anadolu\'nun güney ve alçak kesimleri ılıman kalmış; türler buralarda yaşamaya devam edip daha sonra yeniden yayılmıştır.'),
  ('Türkiye\'de endemik bitki türlerinin en yoğun bulunduğu dağ sistemlerinden biri olan ve kireçtaşı kayalıklarıyla bilinen sıradağlar hangisidir?', 'Toros Dağları', ['Istranca Dağları', 'Yıldız Dağları', 'Kocaeli Platosu'], 'Toroslar engebeli yapısı, farklı yükselti kuşakları ve kireçtaşı ortamlarıyla çok sayıda endemik bitkiye ev sahipliği yapar.'),
  ('Tuz Gölü çevresinde yalnızca orada bulunan pek çok bitki türünün yaşaması en çok hangi özelliğe uyum sağlamalarıyla açıklanır?', 'Toprağın çok tuzlu olmasına', ['Sürekli yüksek yağış almasına', 'Tropikal sıcaklıklara', 'Yoğun ormanlarla çevrili olmasına'], 'Tuz Gölü havzasının tuzlu toprakları ancak halofit bitkilerin yaşayabileceği özel bir ortam oluşturur; bu ortamda evrimleşen bazı türler başka yerde bulunmaz.'),
  ('Bir bitki türünün Türkiye\'de endemik olduğu söyleniyor. Bu bilgiye göre aşağıdakilerden hangisi kesinlikle doğrudur?', 'Türün doğal yayılışı Türkiye sınırları içindedir', ['Tür Türkiye\'nin her ilinde yetişir', 'Türün nesli tehlikede değildir', 'Tür başka ülkelerde de doğal olarak geniş alanlarda yetişir'], 'Endemik olmak yayılışın sınırlı olduğunu gösterir; türün ülkenin her yerinde bulunduğunu ya da tehlikede olup olmadığını tek başına söylemez.'),
  ('Kışın sonunda Ankara çevresinde kar kalkar kalkmaz açan, turuncu-sarı çiçekli ve Türkiye\'ye endemik olan çiğdem türü hangisidir?', 'Ankara çiğdemi (Crocus ancyrensis)', ['Safran (Crocus sativus)', 'Ters lale (Fritillaria imperialis)', 'Kardelen (Galanthus elwesii)'], 'Crocus ancyrensis İç Anadolu\'nun bozkır ve açıklıklarında erken ilkbaharda çiçeklenir ve Türkiye\'ye endemiktir.'),
  ('Isparta-Eğirdir yöresindeki Kasnak Ormanı ile adı birlikte anılan ve Türkiye\'ye endemik olan meşe türü hangisidir?', 'Kasnak meşesi (Quercus vulcanica)', ['Mantar meşesi (Quercus suber)', 'Kermes meşesi (Quercus coccifera)', 'Saplı meşe (Quercus robur)'], 'Kasnak meşesi Türkiye\'nin göller yöresi ve çevresindeki dağlarda yetişen endemik bir meşedir; Kasnak Meşesi Ormanı bu türü korumak için koruma altına alınmıştır.'),
  ('Türkiye\'ye endemik ağaçlar arasında yer alan Kazdağı göknarı ile Uludağ göknarı için aşağıdakilerden hangisi doğrudur?', 'İkisi de herdem yeşil kozalaklı ağaçlardır', ['İkisi de yapraklarını kışın döker', 'İkisi de Doğu Anadolu bozkırlarında yaygın olarak yetişir', 'İkisi de çiçek ve meyve oluşturan kapalı tohumlulardır'], 'Kazdağı göknarı ve Uludağ göknarı göknar cinsine (Abies) ait, iğne yapraklarını kışın dökmeyen açık tohumlu kozalaklılardır; biri Kaz Dağları\'nda, diğeri Batı Karadeniz dağlarında yetişir.'),
  ('Muğla ve çevresinde yetişen, gövdesinden \'günlük yağı\' adı verilen kokulu bir reçine elde edilen ve dünyada doğal yayılışı çok dar olan ağaç hangisidir?', 'Anadolu sığlası (Liquidambar orientalis)', ['Kızılçam (Pinus brutia)', 'Defne (Laurus nobilis)', 'Keçiboynuzu (Ceratonia siliqua)'], 'Anadolu sığlası esas olarak Türkiye\'nin güneybatısında, Köyceğiz ve Marmaris çevresinde yetişir; kabuğunun yaralanmasıyla elde edilen balsam parfüm ve ilaç yapımında kullanılmıştır.'),
  ('Anadolu sığlası ormanları genellikle hangi tür ortamlarda bulunur?', 'Taban suyu yüksek ova ve dere kenarlarında', ['Çöl kumullarının ortasında', 'Alpin kuşakta kar sınırının üstünde', 'Tuzlu göllerin kurumuş tabanında'], 'Sığla nemli, taban suyu yüksek alüvyal toprakları sever; Köyceğiz Gölü çevresindeki ovalarda sığla ormanları bu nedenle yoğundur.'),
  ('Türkiye\'de doğal olarak yetişen tek palmiye türü olan ve Datça ile Bodrum yarımadalarında küçük topluluklar hâlinde bulunan bitki hangisidir?', 'Datça hurması (Phoenix theophrasti)', ['Hurma ağacı (Phoenix dactylifera)', 'Cüce palmiye (Chamaerops humilis)', 'Kanarya hurması (Phoenix canariensis)'], 'Phoenix theophrasti Girit ve Güneybatı Anadolu kıyılarında yetişen yabani bir hurmadır; Türkiye\'deki toplulukları koruma altındadır.'),
  ('Datça hurması ve Anadolu sığlası gibi türlerin dar alanlarda yaşaması genellikle geçmişte daha geniş yayılmış florların kalıntısı olarak yorumlanır. Bu türler için en uygun terim hangisidir?', 'Relikt türler', ['İstilacı türler', 'Kozmopolit türler', 'Kültür türleri'], 'Bu türler geçmiş jeolojik dönemlerden kalan ve bugün sığınak alanlarda varlığını sürdüren topluluklar olarak değerlendirilir.'),
  ('Hakkari ve Doğu Anadolu dağlarında yetişen, çiçekleri baş aşağı sarkan ve çiçeklerinin dibinde biriken nektar damlaları nedeniyle halk arasında \'ağlayan gelin\' de denilen bitki hangisidir?', 'Ters lale', ['Kardelen', 'Sümbül', 'Nergis ya da zambak'], 'Ters lale (Fritillaria imperialis) iri, sarkık turuncu-kırmızı çiçekleri ve tepesindeki yaprak demetiyle tanınır; çiçeklerin içindeki nektar damlaları gözyaşına benzetilir.'),
  ('Türkiye\'de birçok geofitin ilkbaharın başında kısa sürede çiçek açıp yaprak verdikten sonra toprak üstü kısımlarını kurutmasının en akla yatkın nedeni nedir?', 'Yazın kuraklığından önce yaşam döngüsünü tamamlamak', ['Kışın kar altında fotosentez yapmak', 'Sonbaharda böceklerden kaçmak', 'Yazın sıcağında daha çok polen üretip rüzgârla dağıtmak'], 'Akdeniz ve karasal iklimlerde ilkbahar nemli ve ılımandır; geofitler bu kısa dönemi kullanır, kurak yazı ise depo organlarında dinlenerek geçirir.'),
  ('Safran baharatı, Crocus sativus çiçeğinin hangi kısmının kurutulmasıyla elde edilir?', 'Dişi organın tepecik kolları', ['Taç yaprakları', 'Soğanı', 'Erkek organların başçıkları ve polenleri'], 'Safran, her çiçekte üç adet olan kırmızı tepecik kollarından elde edilir; elle toplandığı için dünyanın en pahalı baharatlarındandır.'),
  ('Bir kilogram safran elde etmek için on binlerce çiçeğin toplanması gerekir. Bunun temel nedeni aşağıdakilerden hangisidir?', 'Her çiçekten yalnızca birkaç ince tepecik elde edilmesi', ['Safran çiçeklerinin her yıl yalnızca bir kez açması', 'Safran soğanlarının çok ağır olması', 'Safranın yapraklarından elde edilmesi'], 'Her çiçekte yalnızca üç küçük tepecik kolu bulunur ve kuruyunca ağırlıkları çok azalır; bu yüzden çok sayıda çiçek gerekir.'),
  ('Bitki türlerinin doğal yaşam alanları içinde, örneğin bir tabiat koruma alanında korunmasına ne ad verilir?', 'Yerinde (in situ) koruma', ['Yer dışında (ex situ) koruma', 'Doku kültürüyle koruma', 'Herbaryumda koruma'], 'In situ koruma, türü doğal ekosistemiyle birlikte korur; türün evrimsel ilişkileri ve çevresiyle etkileşimi sürer.'),
  ('Türkiye\'nin bitki genetik kaynaklarını uzun süre saklamak amacıyla Ankara\'da kurulan tesisin adı nedir?', 'Türkiye Tohum Gen Bankası', ['Svalbard Küresel Tohum Kasası', 'Kew Botanik Bahçesi', 'Millennium Tohum Bankası'], 'Türkiye Tohum Gen Bankası 2010 yılında Ankara\'da hizmete girmiştir; yabani ve kültür bitkilerine ait tohumları uzun süre saklar.'),
  ('Tohumların gen bankalarında uzun yıllar canlı kalabilmesi için genellikle hangi koşullarda saklanır?', 'Kurutulmuş olarak ve dondurucu soğuklukta', ['Islak ve oda sıcaklığında', 'Güneş ışığı alan sıcak odalarda', 'Su dolu kaplarda, karanlık ve ılık ortamda'], 'Nemi düşürülmüş tohumlar eksi derecelerde saklandığında metabolizmaları çok yavaşlar; böylece onlarca yıl çimlenme yeteneklerini koruyabilirler.'),
  ('Canlı ağaç ve çalıların bilimsel ve eğitsel amaçla bir arada yetiştirildiği bahçeye ne ad verilir?', 'Arboretum', ['Herbaryum', 'Sera', 'Fidanlık deposu'], 'Arboretumlar özellikle odunsu bitkilere ayrılmış botanik bahçeleridir; İstanbul\'daki Atatürk Arboretumu buna örnektir.'),
  ('İstanbul Ataşehir\'de kurulan ve Türkiye florasının tanıtılması ve korunması amacıyla çalışmalar yürüten botanik bahçesi hangisidir?', 'Nezahat Gökyiğit Botanik Bahçesi', ['Kew Kraliyet Botanik Bahçesi', 'Svalbard Tohum Bahçesi', 'Kirstenbosch Botanik Bahçesi'], 'Nezahat Gökyiğit Botanik Bahçesi, otoyol kavşağı içindeki bir alanda kurulmuş, Türkiye bitkilerine ait koleksiyonlarıyla tanınan bir bahçedir.'),
  ('Uluslararası Doğayı Koruma Birliği\'nin (IUCN) Kırmızı Liste sınıflandırmasında, doğada neslinin tükenmesi bakımından en yüksek risk taşıyan kategori hangisidir?', 'Kritik tehlikede (CR)', ['Hassas (VU)', 'Tehdide yakın (NT)', 'Düşük riskli, en az endişe verici (LC)'], 'IUCN kategorileri riskin artış sırasıyla düşük riskli, tehdide yakın, hassas, tehlikede ve kritik tehlikede şeklinde sıralanır; ardından doğada tükenmiş ve tükenmiş gelir.'),
  ('Bir bölgeye endemik bir bitki türünün yaşadığı tek vadide baraj yapılması planlanıyor. Türün korunması açısından aşağıdakilerden hangisi en etkili ve kalıcı önlem olur?', 'Barajın yerini değiştirip türün yaşam alanını korumak', ['Türün birkaç bireyini saksıya alıp evde yetiştirmek', 'Türün fotoğraflarını çekip arşivlemek', 'Vadideki bitkilerin tamamını başka bir ülkeye taşımak'], 'Yaşam alanının korunması türü doğal ilişkileriyle birlikte yaşatır. Tohum ve canlı koleksiyonlar destekleyici önlemlerdir ama doğal popülasyonun yerini tutmaz.'),
  ('Kaz Dağları\'nın bitki çeşitliliği bakımından özel bir yere sahip olmasının nedenlerinden biri aşağıdakilerden hangisidir?', 'Kısa mesafede deniz kıyısından yüksek zirvelere ulaşan farklı iklim kuşakları', ['Tamamen düz ve tek tip topraklara sahip olması', 'Yıl boyunca karla örtülü olup hiç bitki barındırmaması', 'Bütün yüzeyinin tuzlu göllerle kaplı olması'], 'Kaz Dağları Ege kıyısından kısa mesafede 1700 metreyi aşan yükseltilere ulaşır; farklı yükselti kuşakları ve nemli kuzey yamaçları çok sayıda farklı habitat oluşturur.'),
  ('Sıtma tedavisinde yüzyıllarca kullanılan kinin hangi bitkinin kabuğundan elde edilir?', 'Kınakına ağacı (Cinchona)', ['Porsuk ağacı (Taxus)', 'Yüksük otu (Digitalis)', 'Haşhaş (Papaver) ve gelincik'], 'Güney Amerika\'nın And Dağları\'na özgü Cinchona ağaçlarının kabuğundan elde edilen kinin, sıtma etkenine karşı ilk etkili ilaçlardandır.'),
  ('Kalp yetmezliği tedavisinde kullanılan digoksin gibi ilaçların kaynağı olan ve çan biçimli çiçekleri bir başak boyunca dizilen bitki hangisidir?', 'Yüksük otu', ['Isırgan otu', 'Ebegümeci', 'Kantaron'], 'Yüksük otu (Digitalis) kalp kasının kasılmasını güçlendiren kalp glikozitleri içerir; doğru dozda ilaç, fazlası zehirdir.'),
  ('Kahve bitkisinin en çok tüketilen türü olan Coffea arabica\'nın anavatanı olarak kabul edilen yer neresidir?', 'Etiyopya\'nın dağlık bölgeleri', ['Brezilya\'nın kıyı ovaları', 'Kolombiya\'nın And Dağları', 'Endonezya\'nın Java ve Sumatra adaları'], 'Coffea arabica\'nın doğal yayılışı Etiyopya yaylalarıdır; kahve buradan Yemen\'e, oradan da Osmanlı topraklarına ve dünyaya yayılmıştır.'),
  ('Kakao ağacının çekirdekleri çikolata yapımında kullanılır. Bu ağacın meyveleri ağaçta nerede gelişir?', 'Doğrudan gövde ve kalın dallar üzerinde', ['Yalnızca toprak altında', 'İnce dal uçlarındaki kozalaklarda', 'Yaprakların alt yüzeyinde, sap boyunca'], 'Kakao (Theobroma cacao) gövdede çiçeklenen bir ağaçtır; çiçekleri ve iri meyveleri gövde ve kalın dallardan çıkar.'),
  ('Doğal kauçuğun büyük kısmı hangi ağacın gövdesi çizilerek toplanan süt benzeri özsuyundan elde edilir?', 'Kauçuk ağacı (Hevea brasiliensis)', ['Kauçuk inciri (Ficus elastica)', 'Akdeniz sakız ağacı (Pistacia lentiscus)', 'Şeker akçaağacı (Acer saccharum)'], 'Amazon kökenli Hevea brasiliensis\'in lateksi doğal kauçuğun ana kaynağıdır; bugün en çok Güneydoğu Asya\'da yetiştirilir.'),
  ('Çeşme yöresinde yetişen ve gövdesinden sızan reçinesi sakız olarak toplanan bitki hangisidir?', 'Sakız ağacı (Pistacia lentiscus)', ['Sığla ağacı (Liquidambar orientalis)', 'Fıstık çamı (Pinus pinea)', 'Keçiboynuzu (Ceratonia siliqua)'], 'Sakız ağacı Antep fıstığı ile aynı cinstendir; gövdesine yapılan çiziklerden sızan reçine kuruyunca damla sakızı adıyla bilinir.'),
  ('Antep fıstığı ağacının (Pistacia vera) bahçelerde meyve verebilmesi için erkek ağaçların da dikilmesi gerekir. Bunun nedeni nedir?', 'İki evcikli olup dişi ağaçların erkek ağaçlardan polen alması gerekmesi', ['Erkek ağaçların toprağa azot vermesi', 'Erkek ağaçların dişileri rüzgârdan koruması', 'Erkek ağaçların kökleriyle dişileri sulaması'], 'Antep fıstığında erkek ve dişi çiçekler ayrı ağaçlardadır; rüzgârla taşınan polen olmadan dişi ağaçlar meyve bağlamaz.'),
  ('Pamuk bitkisinde lif olarak işlenen beyaz kısım bitkinin hangi yapısından oluşur?', 'Tohum kabuğu üzerindeki uzun tüylerden', ['Gövdenin iç kısmındaki odundan', 'Yaprakların damarlarından', 'Köklerin dış kabuğundaki mantar dokusundan'], 'Pamuk lifleri tohumun epidermis hücrelerinin uzamasıyla oluşan ve neredeyse saf selülozdan yapılmış tüylerdir.'),
  ('Eski Mısır\'da yazı yüzeyi olarak kullanılan papirüs, hangi tür bitkinin gövdesinden yapılırdı?', 'Nil kıyılarında yetişen bir saz bitkisi', ['Çöllerde yetişen bir kaktüs', 'Dağlarda yetişen bir çam türü', 'Denizde yaşayan büyük bir kahverengi alg'], 'Papirüs (Cyperus papyrus) bataklık ve nehir kıyılarında yetişen bir saz bitkisidir; gövdesinin öz kısmından şeritler kesilip preslenerek yazı yüzeyi hazırlanırdı.'),
  ('Kot kumaşlarının geleneksel mavi rengini veren doğal boya hangi bitki grubundan elde edilirdi?', 'Çivit otu (Indigofera)', ['Kına (Lawsonia inermis)', 'Safran (Crocus sativus)', 'Zerdeçal (Curcuma longa)'], 'Çivit (indigo) boyası Indigofera bitkilerinin yapraklarından elde edilirdi; bugün büyük ölçüde sentetik olarak üretilmektedir.'),
  ('Bambunun bazı türleri bir günde bir metreye yakın uzayabilir. Bu bitki hangi familyanın üyesidir?', 'Buğdaygiller', ['Palmiyegiller', 'Baklagiller', 'Gülgiller'], 'Bambular buğdaygiller (Poaceae) familyasının odunsu üyeleridir; ara meristemleri sayesinde çok hızlı uzarlar.'),
  ('Kâğıt üretiminde odundan elde edilen ve kâğıdın ana yapı taşını oluşturan polimer hangisidir?', 'Selüloz', ['Lignin', 'Nişasta', 'Kitin ve keratin'], 'Odun hamuru üretiminde lignin uzaklaştırılır ve geriye kalan selüloz lifleri kâğıdı oluşturur; lignin kâğıdın zamanla sararmasına neden olur.'),
  ('Bir kültür bitkisinin yabani akrabalarının bir ülkede doğal olarak yetişmesi, bitki ıslahçıları için neden değerlidir?', 'Hastalık ve kuraklığa direnç genleri sağlayabilmeleri', ['Yabani akrabaların daha kolay hasat edilmesi', 'Yabani akrabaların hiç su istememesi', 'Yabani akrabaların her zaman daha tatlı olması'], 'Yabani akrabalar kültür çeşitlerinde kaybolmuş genetik çeşitliliği taşır; ıslahçılar bu genleri kültür bitkilerine aktararak dayanıklı çeşitler geliştirir.'),
  ('Aristoteles\'in öğrencisi olan, bitkileri sistemli olarak inceleyen eserleri nedeniyle \'botaniğin babası\' olarak anılan Antik Yunan düşünürü kimdir?', 'Theophrastos', ['Hipokrat', 'Arşimet', 'Pisagor ya da Öklid'], 'Theophrastos\'un \'Bitkilerin Araştırılması\' ve \'Bitkilerin Nedenleri\' adlı eserleri yüzlerce bitkiyi tanımlayan ilk sistemli botanik çalışmalarıdır.'),
  ('Bilimsel adları \'Abies cilicica\' ve \'Abies nordmanniana\' olan iki ağaç için aşağıdakilerden hangisi kesin olarak söylenebilir?', 'Aynı cinse ait farklı türlerdir', ['Aynı türün iki farklı adıdır', 'Farklı familyalara aittir', 'Biri açık, diğeri kapalı tohumludur'], 'İki adın ilk sözcüğü aynıdır, yani her ikisi de Abies (göknar) cinsindendir; ikinci sözcükler farklı olduğu için farklı türlerdir.'),
  ('Bir bitkinin bilimsel adı \'Crocus ancyrensis\' olarak verilmiştir. Tür sıfatı \'ancyrensis\' büyük olasılıkla neyi anlatır?', 'Türün Ankara ile ilişkili olduğunu', ['Türün çok kokulu olduğunu', 'Türün suda yaşadığını', 'Türün çiçeklerinin kırmızı renkli olduğunu'], 'Ankara\'nın antik adı Ankyra\'dır; \'-ensis\' eki bir yere ait olmayı belirtir. Bu ad türün Ankara çevresinde tanımlandığını gösterir.'),
  ('Mendel\'in kalıtım deneyleri için bezelyeyi seçmesinin avantajlarından biri hangisidir?', 'Kendi kendine tozlaşabilmesi ve çaprazlamanın denetlenebilmesi', ['Bir ağaç olup yüzlerce yıl yaşaması', 'Yalnızca sporla çoğalması', 'Çiçek açmadan tohum vermesi'], 'Bezelye çiçekleri kendini dölleyebildiği için saf hatlar elde etmek kolaydır; araştırmacı polenleri elle aktararak istediği çaprazlamayı yapabilir.'),
  ('İskoç botanikçi Robert Brown, su içindeki polen tanelerinden çıkan küçük parçacıkların düzensiz hareketlerini mikroskopla gözlemlemiştir. Bu hareket bugün hangi adla anılır?', 'Brown hareketi', ['Kepler hareketi', 'Newton hareketi', 'Darwin hareketi'], 'Brown 1827\'de bu düzensiz hareketi tanımlamıştır; hareketin su moleküllerinin çarpmasından kaynaklandığı daha sonra açıklanmıştır. Brown ayrıca hücre çekirdeğini de tanımlamıştır.'),
  ('Norman Borlaug\'un 20. yüzyılda geliştirdiği kısa boylu ve yüksek verimli buğday çeşitleriyle anılan tarımsal dönüşüm hangi adla bilinir?', 'Yeşil Devrim', ['Sanayi Devrimi', 'Mavi Devrim', 'Neolitik Devrim'], 'Yeşil Devrim, yüksek verimli tahıl çeşitleri, gübre ve sulamanın yaygınlaşmasıyla birçok ülkede gıda üretimini kısa sürede artırmıştır. Borlaug 1970\'te Nobel Barış Ödülü almıştır.'),
  ('Yabani buğdaylarda olgun başaklar kendiliğinden dağılıp tohumlarını yere döker; kültür buğdaylarında ise başak hasada kadar bütün kalır. Bu farkın ortaya çıkması en iyi nasıl açıklanır?', 'İlk çiftçilerin dağılmayan başakları seçerek ekmesi', ['Kültür buğdayının tamamen farklı bir familyadan gelmesi', 'Toprağa verilen gübrenin başakları sertleştirmesi', 'Kültür buğdayının yalnızca kışın yetişmesi'], 'Hasatta dağılmayan başaklar daha kolay toplanıp ertesi yıl ekildiği için bu özellik nesiller boyu seçilerek kültür buğdaylarında yaygınlaşmıştır.'),
  ('Bir tarımcı, kuraklığa dayanıklı bir buğday çeşidi geliştirmek için Türkiye\'nin kurak bozkırlarında yetişen yabani buğday akrabalarından örnek topluyor. Bu çalışmanın temelindeki düşünce nedir?', 'Yabani topluluklar zorlu koşullara uyum sağlayan genler taşıyabilir', ['Yabani bitkiler kültür bitkilerinden her zaman daha verimlidir', 'Bozkır bitkilerinin tamamı buğday türüdür', 'Yabani bitkiler hiçbir zaman hastalanmaz'], 'Doğal seçilim kurak bozkırlarda kuraklığa dayanıklılık sağlayan özellikleri korur; bu genler melezleme yoluyla kültür çeşitlerine aktarılabilir.'),
  ('Kristof Kolomb sonrasında Avrupa\'dan Amerika\'ya taşınan bitkilere bir örnek hangisidir?', 'Buğday', ['Patates', 'Domates', 'Tütün'], 'Buğday Eski Dünya kökenli bir tahıldır ve Amerika\'ya Avrupalılarla taşınmıştır; patates, domates ve tütün ise Amerika\'dan Eski Dünya\'ya geçmiştir.'),
  ('Bir yıllık halkada açık renkli ve geniş hücreli ilkbahar odunu ile koyu renkli ve sık hücreli yaz odunu görülür. Bu farkın nedeni nedir?', 'İlkbaharda bol su ve hızlı büyüme, yaz sonunda yavaşlama', ['İlkbaharda ağacın yapraklarını dökmesi', 'Yazın kambiyumun tamamen durması ve hücrelerin ölmesi', 'Kışın kar suyunun halkaları boyaması'], 'İlkbaharda su ve büyüme hormonları bol olduğu için geniş hücreler oluşur; yaz sonuna doğru büyüme yavaşlar ve hücreler küçük, duvarlar kalın olur.'),
  ('Ağaçların yıllık halkalarını inceleyerek geçmişteki iklim olaylarını ve ahşap yapıların yaşını belirleyen bilim dalına ne ad verilir?', 'Dendrokronoloji', ['Palinoloji', 'Mikoloji', 'Fenoloji ya da paleontoloji'], 'Dendrokronoloji halka genişliklerindeki desenleri karşılaştırarak yılları tarihlendirir; arkeolojide ahşap kalıntıların tarihlenmesinde kullanılır.'),
  ('Ekvator çevresindeki yağmur ormanlarında yetişen ağaçların çoğunda belirgin yıllık halkalar görülmez. Bunun nedeni nedir?', 'Yıl boyunca sıcaklık ve yağışın fazla değişmemesi', ['Bu ağaçların kambiyumu olmaması', 'Bu ağaçların tümünün tek çenekli olması', 'Bu ağaçların yalnızca birkaç yıl yaşaması'], 'Mevsim farkının belirgin olmadığı yerlerde büyüme yıl boyunca benzer hızda sürer; bu yüzden açık ve koyu bantlar ayırt edilemez.'),
  ('Bir ağaç gövdesinin ortasında bulunan, artık su taşımayan, genellikle koyu renkli ve sağlam odun kısmına ne ad verilir?', 'Öz odun', ['Diri odun', 'Kabuk', 'Kambiyum'], 'Öz odun yaşlanıp iletim görevini bırakmış ksilemdir; reçine ve tanen gibi maddeler birikerek koyulaşır ve gövdeye destek sağlar. Dıştaki açık renkli diri odun ise su taşır.'),
  ('İçi oyulmuş yaşlı bir çınar ağacının yüzyıllarca yaşamaya ve yaprak vermeye devam edebilmesi nasıl açıklanır?', 'Su ve besin taşıyan canlı dokular gövdenin dış kısmındadır', ['Ağacın tüm yaşamsal işlevleri kökte gerçekleşir', 'Çınar ağaçları suyu yapraklarından emer', 'Gövdenin içi oyulunca ağaç fotosentezi bırakır'], 'Diri odun, kambiyum ve floem gövdenin dış katmanlarındadır; ortadaki öz odun cansızdır ve kaybedilse de ağaç yaşamını sürdürebilir.'),
  ('Bir ağacın gövdesine yerden 1 metre yükseklikte bir çivi çakılıyor. Ağaç 10 yıl boyunca boyca 5 metre uzuyor. Çivi 10 yıl sonra yerden yaklaşık ne yükseklikte olur?', 'Yerden yaklaşık bir metrede', ['Yerden yaklaşık altı metrede', 'Yerden yaklaşık üç buçuk metrede', 'Yerden yaklaşık beş metrede'], 'Boyca uzama yalnızca sürgün uçlarındaki meristemlerde olur; gövdenin var olan kısmı uzamaz, bu nedenle çivi aynı yükseklikte kalır.'),
  ('Tropikal yağmur ormanlarında büyük ağaçların gövde tabanında görülen geniş, kanat biçimli kökler ağaçlara hangi yararı sağlar?', 'Sığ topraklarda dengeyi artırır', ['Böcekleri yakalayıp sindirir', 'Yağmur suyunu depolar', 'Tohumları rüzgârla uzaklara dağıtır'], 'Payanda kökler denen bu yapılar, besinlerin yüzeyde toplandığı sığ topraklarda uzun ağaçların devrilmesini önler.'),
  ('Taygada iğne yapraklı ağaçların yaygın, geniş yapraklı ağaçların az olmasını en iyi açıklayan özellik hangisidir?', 'Kısa büyüme mevsiminde hemen fotosenteze başlayabilmeleri', ['Taygada hiç kar yağmaması', 'Geniş yapraklı ağaçların soğukta daha hızlı büyümesi', 'İğne yaprakların böcekleri çekmesi'], 'Herdem yeşil iğne yapraklılar baharda yeni yaprak üretmek zorunda kalmadan hemen fotosenteze başlar; kısa yazın bu, büyük bir avantaj sağlar.'),
  ('Türkiye\'de Karadeniz kıyısından iç kesimlere doğru dağlara çıkıldıkça genellikle hangi orman dizilimi görülür?', 'Geniş yapraklılar, karışık orman, iğne yapraklılar', ['İğne yapraklılar, maki, geniş yapraklılar', 'Maki, tayga, mangrov', 'Bozkır, geniş yapraklılar, maki'], 'Kıyıdaki nemli ve ılık alanlarda kayın, kestane, gürgen gibi geniş yapraklılar; yükseldikçe karışık ormanlar, daha yukarıda ladin, göknar ve sarıçam gibi iğne yapraklılar yer alır.'),
  ('Bir dağın kuzey ve güney yamaçlarında farklı orman türlerinin yetişmesinin başlıca nedeni hangisidir?', 'Yamaçların güneşlenme ve nem bakımından farklı olması', ['Kuzey yamaçların her zaman deniz kıyısında olması', 'Güney yamaçlarda toprağın hiç bulunmaması', 'Bitkilerin pusula gibi yön seçmesi'], 'Kuzey Yarım Küre\'de güney yamaçlar daha çok güneş alır, daha sıcak ve kurudur; kuzey yamaçlar ise daha serin ve nemlidir. Bu fark ağaç türlerinin dağılışını etkiler.'),
  ('Bir ormancı, Akdeniz kıyısında yazları çok kurak geçen sığ ve kayalık yamaçlarda yerli bir türle ağaçlandırma yapacaktır. Aşağıdaki ağaçlardan hangisini seçmesi en uygun olur?', 'Kızılçam', ['Doğu ladini', 'Doğu kayını', 'Kızılağaç'], 'Akdeniz ikliminin kurak yaz koşullarına ve sığ topraklara en iyi uyum sağlamış yerli tür kızılçamdır; diğerleri nemli ve serin ortamları tercih eder.'),
  ('Bitki hücre duvarının ana maddesi olan selüloz, insan sindiriminde enerji kaynağı olarak kullanılamaz ama yine de beslenmede önemlidir. Bunun nedeni nedir?', 'Lif olarak bağırsak hareketlerini destekler', ['Vücutta doğrudan kas proteinine dönüşür', 'Kanda oksijen taşır', 'Kemiklerin ana yapısını oluşturur'], 'İnsanlar selülozu parçalayan enzime sahip değildir; selüloz sindirilmeden lif olarak geçer ve sindirim sisteminin düzenli çalışmasına yardım eder.'),
  ('İnek ve keçi gibi otçul hayvanların selülozdan enerji elde edebilmesini sağlayan nedir?', 'Sindirim sistemlerindeki selülozu parçalayan mikroorganizmalar', ['Kendi tükürüklerinde selüloz bulunmaması', 'Selülozu güneşte kurutup yemeleri', 'Yalnızca bitki köklerini yemeleri'], 'Geviş getiren hayvanların işkembesinde yaşayan bakteri ve tek hücreliler selülozu parçalar; hayvan bu ürünlerden enerji sağlar.'),
  ('Kesilmiş çiçekleri vazoda daha uzun süre taze tutmak için sapın ucu genellikle su altında ve eğik olarak kesilir. Bunun temel amacı nedir?', 'Ksileme hava girmesini önleyip su emilim yüzeyini artırmak', ['Çiçeğin yapraklarını daha çabuk döküp güzelleştirmek', 'Sapın fotosentez yapmasını sağlamak', 'Polen üretimini durdurmak'], 'Sap havada kesilince iletim borularına hava kabarcıkları girip su sütununu kesebilir; su altında eğik kesmek bunu önler ve emici yüzeyi büyütür.'),
  ('Bir bahçıvan gübreyi aşırı miktarda verdiğinde bitkilerin solduğunu görüyor. Bunun en olası açıklaması nedir?', 'Toprak çözeltisi yoğunlaşınca köklerin su alamaması', ['Gübrenin yaprakları güneşten koruması', 'Gübrenin fotosentezi hızlandırması', 'Köklerin gübreyi doğrudan enerjiye çevirmesi'], 'Aşırı gübre topraktaki tuz derişimini artırır; ozmoz nedeniyle su köke girmek yerine kökten dışarı çıkmaya başlar ve bitki solar.'),
  ('Kışın buzlanmaya karşı yollara atılan tuzun yol kenarındaki ağaçlara zarar vermesinin başlıca nedeni hangisidir?', 'Toprağın tuzlanmasıyla köklerin su almakta zorlanması', ['Tuzun ağaçlara fazladan ışık yansıtması', 'Tuzun yaprakların donmasını hızlandırması', 'Tuzun kabuğu tamamen eritmesi'], 'Tuzlu toprak ozmotik olarak köklerden su çeker; ayrıca sodyum ve klor iyonları dokularda birikerek zehirli etki yapar.'),
  ('Aynı yaştaki iki fidandan biri açık alanda, diğeri sık bir ormanın gölgesinde yetişiyor. Gölgedeki fidanın genellikle daha ince ve daha uzun gövdeli olmasının nedeni nedir?', 'Işığa ulaşmak için gövdenin uzamaya yönelmesi', ['Gölgede kökün daha hızlı büyümesi', 'Gölgede yaprakların daha kalın olması', 'Ormandaki fidanın fotosentez yapmaması'], 'Işığı az alan bitkiler kaynaklarını boyca uzamaya ayırır; bu sayede komşu bitkilerin üstüne çıkıp ışığa ulaşma şansını artırır.'),
  ('Karanlıkta çimlenen fasulye fidelerinin uzun, ince, solgun sarı gövdeli ve küçük yapraklı olmasına ne ad verilir?', 'Etiyolasyon', ['Plazmoliz', 'Gutasyon', 'Vernalizasyon'], 'Işıksız ortamda klorofil sentezlenmez ve fide ışık bulmak için hızla uzar; bu solgun ve cılız büyüme etiyolasyon olarak adlandırılır.'),
  ('Bir bahçede domates bitkilerinin yan sürgünleri düzenli olarak kopartılıyor. Bu uygulamanın amacı nedir?', 'Besinlerin meyvelere yönelmesini sağlamak', ['Bitkinin daha çok yaprak vermesini sağlamak', 'Köklerin topraktan daha az su almasını sağlamak', 'Bitkinin hiç meyve vermemesini sağlamak'], 'Gereksiz yan sürgünler fotosentez ürünlerini kendi büyümelerine harcar; bunlar alınınca besinler var olan meyvelere yönlenir ve daha iri meyve elde edilir.'),
  ('Sonbaharda bir ağacın bazı yaprakları dökülmeden önce sararıyor; ancak ağaç bu yapraklardaki azot ve magnezyumun bir kısmını gövdeye geri çekiyor. Bu davranışın ağaç için yararı nedir?', 'Değerli besin elementlerini ertesi yıl için saklamak', ['Yaprakları daha ağır hâle getirip düşürmek', 'Yaprakların yeniden yeşermesini sağlamak', 'Böcekleri yaprağa çekmek'], 'Yaprak dökülmeden önce klorofil gibi moleküller parçalanır ve azot, fosfor, magnezyum gibi elementler gövdeye taşınarak sonraki büyüme mevsiminde kullanılır.'),
  ('Çok küçük tohumlu bitkilerin, örneğin marul ya da bazı orkidelerin tohumlarının toprağın derinine ekilmemesi önerilir. Bunun başlıca nedeni nedir?', 'Küçük tohumların besin deposu fidenin yüzeye çıkmasına yetmez', ['Küçük tohumlar toprak altında suyla dolar', 'Derinde çimlenen tohumlar hep çift çenekli olur', 'Toprak derinliği tohumları tuzlu yapar'], 'Küçük tohumlar az besin depolar; derine ekilirse fide ışığa ulaşmadan bu besin tükenir. Ayrıca bazı küçük tohumlar çimlenmek için ışık ister.'),
  ('Bir kayısı ağacında çiçekler ilkbaharın başında açtıktan sonra gelen geç bir don, o yılın ürününü büyük ölçüde yok edebilir. Bunun en doğrudan nedeni nedir?', 'Dişi organların dondan zarar görmesiyle döllenmenin gerçekleşmemesi', ['Kök sisteminin tamamen kuruması', 'Gövdedeki yıllık halkaların bozulması', 'Yaprakların dökülüp bir daha çıkmaması'], 'Çiçek dokuları, özellikle dişi organ ve genç meyveler dona çok duyarlıdır; zarar gören çiçekler meyve bağlayamaz. Malatya\'da geç donlar bu yüzden çok korkulur.'),
  ('Bir botanikçi Toros Dağları\'nda daha önce hiç kaydedilmemiş bir bitki buluyor ve yalnızca birkaç vadide yetiştiğini belirliyor. Bu bitkinin bilim dünyasına yeni tür olarak tanıtılması için atması gereken temel adım hangisidir?', 'Örnek toplayıp bilimsel bir yayında tanımlamak', ['Bitkiyi pazarda satışa sunmak', 'Bitkiye yalnızca yerel bir ad vermek', 'Bitkiyi başka bir ülkeye taşımak'], 'Yeni bir tür, bir herbaryuma konan tip örneğe dayanılarak bilimsel bir yayında tanımlandığında ve kurallara uygun bir bilimsel ad aldığında geçerlilik kazanır.'),
  ('Bir dağ köyünde endemik bir çiçeğin soğanlarını toplayıp satan köylülerin bu türün geleceğini tehlikeye atmaması için aşağıdaki çözümlerden hangisi hem doğayı hem geçimi en iyi gözetir?', 'Soğanları denetimli üretim alanlarında çoğaltıp satmak', ['Doğadaki bütün soğanları bir defada toplamak', 'Türün yaşadığı alanı tarlaya dönüştürmek', 'Soğanları toplamayı serbest bırakıp hiç denetlememek'], 'Kültür ortamında üretim doğal topluluklar üzerindeki baskıyı azaltır ve köylülere gelir sağlamaya devam eder; doğadan sınırsız toplama türün yok olmasına yol açabilir.'),
  ('Endemik bir bitki yalnızca tek bir böcek türü tarafından tozlaştırılıyor. Bölgede tarım ilacı kullanımı nedeniyle bu böcek yok olursa bitkiyi en çok hangi tehlike bekler?', 'Tohum üretememe ve zamanla neslinin tükenmesi', ['Çiçeklerinin daha büyük olması', 'Rüzgârla tozlaşmaya hemen geçmesi', 'Yapraklarının renginin değişmesi'], 'Tek tozlaştırıcıya bağımlı bitkiler bu ortağı kaybedince eşeyli üreyemez; yeni bireyler oluşmadığı için topluluk zamanla yok olur.'),
  ('Sarı çiçekleri zeytinyağında bekletilerek kırmızı renkli \'kantaron yağı\' hazırlanan ve halk arasında yara iyileştirmede kullanılan bitki hangisidir?', 'Sarı kantaron (Hypericum perforatum)', ['Yüksük otu (Digitalis purpurea)', 'Isırgan otu (Urtica dioica)', 'Zakkum (Nerium oleander) ve akrabaları'], 'Hypericum perforatum\'un çiçeklerindeki hiperisin gibi maddeler yağa kırmızı renk verir; bitkinin yaprakları ışığa tutulunca küçük delikler varmış gibi görünür.'),
  ('Sümbül (Hyacinthus orientalis) ile ilgili hangisi doğrudur?', 'Doğal yayılışı Anadolu ve Doğu Akdeniz çevresindedir', ['Anavatanı Güney Amerika\'dır', 'Kozalaklı bir ağaçtır', 'Yalnızca su altında yetişir'], 'Bahçelerde yetiştirilen sümbüllerin yabani atası Hyacinthus orientalis\'tir; Güney Anadolu, Suriye ve Lübnan çevresinde doğal olarak yetişir.'),
  ('Siklamen (tavşankulağı) bitkilerinin besin depolayan toprak altı organı hangisidir?', 'Yumru', ['Soğan', 'Rizom', 'Stolon'], 'Siklamenler yassı ve yuvarlak bir yumru taşır; bu yumru yıllarca büyüyerek bitkinin kurak dönemi atlatmasını sağlar.'),
  ('Anadolu sığlası ormanlarının bir bölümünün tarım alanına dönüştürülmesi, türün geleceği açısından neden özellikle önemli bir tehdittir?', 'Türün dünyadaki yayılışının çok dar olması', ['Sığlanın her ülkede kolayca yetişmesi', 'Sığlanın çok hızlı yayılan bir yabancı tür olması', 'Sığlanın yalnızca çölde yaşayabilmesi'], 'Sığlanın doğal yayılışı büyük ölçüde Güneybatı Anadolu ile sınırlıdır; bu alanların kaybı türün dünya genelindeki varlığını doğrudan tehdit eder.'),
  ('Kasnak meşesi ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Türkiye dışında doğal olarak yetiştiği bilinmez', ['Kuzey Avrupa\'nın en yaygın meşesidir', 'Kozalak oluşturan bir açık tohumludur', 'Yapraklarını hiç dökmeyen tropikal bir ağaçtır'], 'Kasnak meşesi Türkiye\'ye endemiktir; Göller Yöresi ve İç Batı Anadolu\'nun dağlık kesimlerinde yetişen, yaprak döken bir meşedir.'),
  ('Makilerde yaygın olan, beyaz çiçekli, koyu mavi-siyah meyveli ve ezilen yaprakları güzel kokan, halk arasında \'murt\' da denen çalı hangisidir?', 'Mersin', ['Kocayemiş', 'Zakkum', 'Keçiboynuzu ağacı'], 'Mersin (Myrtus communis) Akdeniz makisinin tipik herdem yeşil çalılarındandır; yaprakları aromatik yağ bezleri taşır.'),
  ('Uludağ göknarının doğal yayılışı için hangisi doğrudur?', 'Batı Karadeniz dağlarında, Uludağ\'dan Kastamonu\'ya uzanan alanda', ['Doğu Anadolu\'nun yüksek ovalarında', 'Akdeniz kıyısındaki makiliklerde', 'Tuz Gölü havzasının tuzlu düzlüklerinde'], 'Uludağ göknarı Bursa Uludağ\'dan Bolu, Zonguldak ve Kastamonu dağlarına kadar Batı Karadeniz\'in nemli dağ ormanlarında yayılış gösterir.'),
  ('Toros göknarı (Abies cilicica) için aşağıdakilerden hangisi doğrudur?', 'Toroslar\'ın yüksek kesimlerinde sedirle karışık ormanlar kurar', ['Yalnızca deniz kıyısındaki kumullarda yetişir', 'Yapraklarını sonbaharda döken bir kayın türüdür', 'Tropikal yağmur ormanlarının alt katında bulunur'], 'Toros göknarı Toroslar ve Amanoslar\'da genellikle 1200 metreden yukarıda sedir ve karaçamla birlikte ormanlar oluşturur.'),
  ('Türkiye\'de bir türün \'endemik\' olduğu, bir başka türün ise \'yerli\' olduğu söyleniyor. Bu iki kavram arasındaki ilişki için hangisi doğrudur?', 'Endemik türler yerlidir ama her yerli tür endemik değildir', ['Yerli türler her zaman endemiktir', 'Endemik türler başka kıtalardan getirilmiştir', 'İki kavram aynı anlama gelir'], 'Yerli tür bir bölgede doğal olarak bulunan türdür; bunlardan yalnızca orayla sınırlı olanlar endemiktir. Örneğin kızılçam Türkiye\'de yerlidir ama yalnızca Türkiye\'ye özgü değildir.'),
  ('Yanardöner peygamber çiçeği tek yıllık bir bitkidir. Bu bilgi, türün korunmasında hangi noktayı özellikle önemli kılar?', 'Her yıl yeterli tohum üretip toprağa bırakabilmesini', ['Ağaç gibi yüzlerce yıl yaşamasını', 'Soğanının doğadan toplanabilmesini', 'Kökünden yeniden sürgün vermesini'], 'Tek yıllık bitkiler yaşamlarını bir yılda tamamlar ve bir sonraki yıl yalnızca tohumla devam eder; tohum üretimi engellenirse topluluk hızla yok olabilir.'),
  ('Türkiye\'nin \'gen merkezi\' olarak anılmasının sebeplerinden biri aşağıdakilerden hangisidir?', 'Birçok kültür bitkisinin yabani akrabasının burada doğal yetişmesi', ['Bütün kültür bitkilerinin ilk kez Türkiye\'de bulunması', 'Türkiye\'de hiç yabancı bitki bulunmaması', 'Türkiye\'de yalnızca tahıl yetiştirilmesi'], 'Buğday, arpa, nohut, mercimek, fındık ve birçok meyvenin yabani akrabaları Anadolu\'da doğal olarak bulunur; bu da ülkeyi önemli bir genetik kaynak merkezi yapar.'),
  ('Bozkırlarda yaygın görülen ve dikenli, yastık biçimli bir görünüm kazanan gevenlerin bu biçiminin kurak ve rüzgârlı ortamdaki yararı nedir?', 'Su kaybını ve otlanmayı azaltması', ['Bol polen üretmesini sağlaması', 'Su altında fotosentez yapmasını sağlaması', 'Çok hızlı boyca uzamasını sağlaması'], 'Yastık biçimi bitkinin içinde nemli ve korunaklı bir mikroortam oluşturup rüzgârın kurutucu etkisini azaltır; dikenler de hayvanların otlamasını zorlaştırır.'),
  ('Peri bacalarına ve volkanik tüflere yakın bir alanda yalnızca jipsli toprakta yetişen bir bitki bulunuyor. Bu bitkinin başka topraklara taşındığında yaşayamamasının en olası nedeni nedir?', 'Özel toprak koşullarına uyum sağlamış olması', ['Rüzgârın bu bitkiyi hiç taşımaması', 'Başka topraklarda ışık bulunmaması', 'Diğer topraklarda suyun tamamen tuzlu olması'], 'Jips gibi özel topraklara uyum sağlamış türler bu ortamda rakipsizdir; ancak normal topraklarda diğer bitkilerle rekabet edemez ya da gereken koşulları bulamaz.'),
  ('Kereviz sapı ve pazı sapı olarak yediğimiz kısımlar botanik açıdan nedir?', 'Yaprak sapı', ['Kök', 'Meyve', 'Toprak altı gövdesi ve yumru'], 'Kerevizin sap kereviz denen çeşidinde ve pazıda etli kısım yaprak sapıdır; yaprak ayası ucunda bulunur.'),
  ('Enginarda yenen kısım nedir?', 'Açmamış çiçek başının etli tablası ve brakteleri', ['Kökün kalınlaşmış kısmı', 'Olgun tohum kapsülü', 'Toprak altındaki yumru'], 'Enginar papatyagillerdendir; yenen kısım henüz açılmamış iri çiçek başının etli tablası ve onu saran pul yapraklarının dip kısmıdır.'),
  ('Ceviz ve fındığın sert kabuklu yenen kısmıyla ilgili aşağıdakilerden hangisi doğrudur?', 'Yediğimiz iç, tohumun içindeki embriyo ve çeneklerdir', ['Yediğimiz iç meyvenin etli kabuğudur', 'Yediğimiz iç bir köktür', 'Yediğimiz iç çiçek yaprağıdır'], 'Fındık ve cevizde yenen iç, tohumun büyük çeneklerinden oluşur ve yağ bakımından zengindir.'),
  ('Ananas tek bir meyve gibi görünse de botanik açıdan nasıl oluşur?', 'Birçok çiçeğin meyvelerinin kaynaşmasıyla', ['Tek bir çiçeğin tablasından', 'Toprak altındaki bir gövdeden', 'Yaprakların birleşmesinden'], 'Ananasta bir sap çevresindeki onlarca çiçeğin meyveleri birleşip bileşik meyveyi oluşturur; kabuktaki altıgen desenler bu meyvelere karşılık gelir.'),
  ('Kavun ve karpuzda yediğimiz tatlı kısım bitkinin hangi yapısından gelişir?', 'Yumurtalık duvarından', ['Yaprak sapından', 'Kökten', 'Gövde kabuğundan'], 'Kabakgillerin meyvesi yumurtalıktan gelişen ve kalın kabuklu bir üzümsü meyvedir; etli kısım meyve duvarıdır.'),
  ('Kestane ve meşe palamudu gibi sert kabuklu tek tohumlu kuru meyvelere ne ad verilir?', 'Fındıksı meyve', ['Bakla', 'Kapsül', 'Üzümsü meyve'], 'Fındıksı meyvelerde meyve duvarı olgunlaşınca sertleşir ve açılmaz; içinde genellikle tek bir tohum bulunur.'),
  ('Bir üzüm salkımındaki her tane botanik açıdan hangi tip meyvedir?', 'Üzümsü meyve', ['Sert çekirdekli meyve', 'Yalancı meyve', 'Kuru meyve'], 'Üzüm, meyve duvarının tamamı etli ve sulu olan, içinde birkaç tohum bulunan tipik bir üzümsü (bakka) meyvedir.'),
  ('Bazı tohumların üzerindeki besince zengin küçük uzantılar karıncaları çeker. Karıncalar tohumu yuvasına taşır ve uzantıyı yiyip tohumu bırakır. Bu durum bitkiye hangi yararı sağlar?', 'Tohumun uygun bir yere taşınması', ['Tohumun hemen yok edilmesi', 'Bitkinin yapraklarının korunması', 'Çiçeklerin kapanması'], 'Karıncalarla tohum yayılımında tohum ana bitkiden uzaklaştırılır ve çoğu zaman besince zengin yuva çevresinde, korunaklı bir yerde çimlenir.'),
  ('Yengeç otu ve pıtrak gibi bitkilerin tarlalara ve otlaklara hızla yayılmasının bir nedeni hangisidir?', 'Çengelli meyvelerinin hayvan tüyüne ve giysiye takılması', ['Tohumlarının su altında çimlenmesi', 'Çiçeklerinin yalnızca geceleri açması', 'Köklerinin yüzlerce metre uzaması'], 'Çengelli ya da dikenli meyveler geçen hayvanlara ve insanlara takılarak uzaklara taşınır; bu tür bitkiler bu nedenle kolay yayılır.'),
  ('Ayçiçeği tablasında tohumlar birbirini kesen iki yönde sarmallar oluşturacak biçimde dizilir. Bu dizilişin bitkiye en önemli yararı nedir?', 'Tablaya en fazla sayıda tohumun sığması', ['Tohumların suda yüzebilmesi', 'Tablanın her zaman kuzeye bakması', 'Tohumların kendiliğinden fırlaması'], 'Sarmal diziliş, tohumların tabla üzerinde boşluk kalmadan sıkıca yerleşmesini sağlar; sarmal sayıları çoğunlukla Fibonacci dizisindeki ardışık sayılardır.'),
  ('Mantarların uzun süre bitkilerle birlikte sınıflandırılmasına rağmen bugün ayrı bir âlem olarak kabul edilmesinin önemli nedenlerinden biri hangisidir?', 'Fotosentez yapmazlar ve hücre duvarları kitinlidir', ['Yalnızca denizlerde yaşarlar', 'Kökleri ve yaprakları vardır', 'Tohumla ve çiçekle çoğalırlar'], 'Mantarlar klorofil taşımaz, besinlerini dışarıdan emer ve hücre duvarları selüloz yerine kitin içerir; bu özellikler onları bitkilerden ayırır.'),
  ('Karahindiba ve marul gibi bazı bitkilerde yapraklar toprağa yakın, gövdenin dibinde daire şeklinde toplanmıştır. Bu dizilişin bitkiye yararı ne olabilir?', 'Yaprakların birbirini gölgelemeden ışık alması', ['Köklerin tamamen ortadan kalkması', 'Yaprakların suda yüzmesi', 'Çiçeklerin toprak altında açması'], 'Rozet dizilişte yapraklar ışığa açık bir halka oluşturur; ayrıca toprağa yakın durdukları için soğuktan ve rüzgârdan korunur.'),
  ('Bir çiçeğin bütün taç yaprakları toplu hâlde nasıl adlandırılır?', 'Korolla', ['Kaliks', 'Andresyum', 'Ginesyum'], 'Taç yaprakların bütününe korolla, çanak yaprakların bütününe kaliks denir; erkek organların bütünü andresyum, dişi organların bütünü ginesyumdur.'),
  ('Gece açan, beyaz renkli ve güçlü kokulu çiçekler en çok hangi hayvanlarca tozlaştırılır?', 'Gece kelebekleri', ['Kelebekler', 'Sinek kuşları', 'Arılar'], 'Karanlıkta renk değil koku ve açık renk önemlidir; gece kelebekleri bu çiçeklere kokuyla yönelir ve uzun hortumlarıyla nektara ulaşır.'),
  ('Belgrad Ormanı gibi İstanbul çevresindeki ormanlarda en yaygın ağaç grubu hangisidir?', 'Meşe türleri', ['Sedir türleri', 'Ladin türleri', 'Palmiye türleri'], 'İstanbul çevresinin doğal ormanları büyük ölçüde meşelerden oluşur; bunlara kestane, gürgen ve kayın eşlik eder.'),
  ('Çam kozalakları nemli havada kapanır, kuru ve sıcak havada açılır. Bu davranışın tohum yayılımı açısından yararı nedir?', 'Tohumların rüzgârın taşıyabileceği kuru havada dökülmesi', ['Tohumların yağmurla toprağa gömülmesi', 'Tohumların kozalak içinde çürümesi', 'Kozalağın ağaçtan hiç düşmemesi'], 'Kanatlı çam tohumları kuru havada daha iyi uçar; kozalak pullarının nemle kapanması tohumları ıslak havada içeride tutar.'),
  ('Bir çocuk, kozalaklı bir ağacın bütün yıl yeşil kaldığını görüp \'Bu ağaç hiç yaprak dökmüyor\' diyor. Bu ifade için en doğru değerlendirme hangisidir?', 'Yanlıştır; iğneler birkaç yılda bir yavaş yavaş yenilenir', ['Doğrudur; iğne yapraklar ağaç ölene kadar kalır', 'Doğrudur; kozalaklılarda hiç yaprak oluşmaz', 'Yanlıştır; bu ağaçlar her kış bütün iğnelerini döker'], 'Herdem yeşil ağaçlar yapraklarını bir anda dökmez; her iğne birkaç yıl yaşar ve eskiyenler zamanla dökülüp yerini yenilerine bırakır.'),
  ('Meşe, kayın ve gürgen gibi ağaçların büyük çoğunluğu kışın yaprak dökerken bazı meşe türleri, örneğin pırnal ve kermes meşesi, herdem yeşildir. Bu herdem yeşil meşeler Türkiye\'de en çok hangi bölgede görülür?', 'Akdeniz ve Ege kıyılarında', ['Doğu Anadolu\'nun yüksek yaylalarında', 'Karadeniz\'in yüksek dağlarında', 'Tuz Gölü çevresinde'], 'Kermes ve pırnal meşesi sert, dikenli kenarlı yapraklı, kuraklığa dayanıklı türlerdir ve makinin önemli bileşenleridir.'),
  ('Kabuğu çok sert olan bazı tohumların çimlenmesini hızlandırmak için ekimden önce kabuklarının zımparalanması ya da hafifçe çizilmesi hangi amaca yöneliktir?', 'Kabuğun su geçirmesini sağlamak', ['Tohumun ağırlığını artırmak', 'Tohumun rengini değiştirmek', 'Tohumun fotosentez yapmasını sağlamak'], 'Bu işleme skarifikasyon denir; sert kabuk inceltilince su embriyoya ulaşır ve imbibisyonla çimlenme başlar.'),
  ('Kayın ağaçlarının gölgeye dayanıklı fideleri sık ormanın altında yıllarca yaşayabilir. Bu özellik kayının ormanda nasıl bir yer edinmesine yardım eder?', 'Zamanla diğer ağaçların altından yetişip ormanda baskın olmasına', ['Yalnızca açık arazide yetişmesine', 'Hiç tohum vermemesine', 'Kışın yapraklarını tutmasına'], 'Gölgeye dayanıklı fideler yaşlı ağaçlar devrildiğinde açılan boşluğu hızla doldurur; bu nedenle kayın nemli ormanlarda zamanla baskın hâle gelebilir.'),
  ('Bir kesilmiş ağaç kütüğünde halkalar merkeze göre bir tarafta geniş, diğer tarafta dar ise bunun en olası açıklaması nedir?', 'Ağacın bir tarafının daha çok ışık ya da baskı alması', ['Ağacın iki farklı türden oluşması', 'Halkaların her yıl yer değiştirmesi', 'Ağacın yalnızca bir yıl yaşamış olması'], 'Eğimli arazi, tek yönden gelen ışık ya da hâkim rüzgâr gibi etkenler gövdenin bir yanında daha çok odun üretilmesine yol açar.'),
  ('Bir ağacın kabuğu kalınlaşırken dış katmanlarının çatlayıp dökülmesinin nedeni nedir?', 'Gövde içten kalınlaştıkça eski kabuğun esneyememesi', ['Ağacın her yıl kabuğunu bilerek yemesi', 'Kabuğun fotosentezle erimesi', 'Kökten gelen suyun kabuğu yıkaması'], 'Kambiyum gövdeyi her yıl kalınlaştırır; ölü hücrelerden oluşan dış kabuk bu genişlemeye uyum sağlayamaz ve çatlar.'),
  ('Kesilen bir ağaçtan tahta elde edilirken ağacın \'odun\' kısmı gövdedeki hangi dokuya karşılık gelir?', 'Ksilem', ['Floem', 'Epidermis', 'Kök tüyleri'], 'Odun, kambiyumun yıllar boyunca içe doğru ürettiği ksilem katmanlarından oluşur; lignin içeren hücre duvarları ona sertlik verir.'),
  ('Odunun sert ve dayanıklı olmasını sağlayan ve hücre duvarlarında selülozla birlikte bulunan madde hangisidir?', 'Lignin', ['Klorofil', 'Nişasta', 'Pektin'], 'Lignin hücre duvarlarını sertleştiren karmaşık bir polimerdir; ağaçların yerçekimine karşı dik durmasını ve suyun yüksek basınçla taşınmasını mümkün kılar.'),
  ('Türkiye\'de ormanlık alanların büyük kısmı dağlık bölgelerde bulunur. Bunun nedeni olarak hangisi en doğrudur?', 'Ova ve düzlüklerin büyük ölçüde tarım ve yerleşim için açılmış olması', ['Ağaçların yalnızca yüksek yerlerde çimlenebilmesi', 'Ovaların hiç yağış almaması', 'Dağlarda toprağın daha tuzlu olması'], 'Düz ve verimli alanlar tarih boyunca tarla ve yerleşime dönüştürülmüştür; ormanlar daha çok işlenmesi zor eğimli dağ arazilerinde kalmıştır.'),
  ('Çınar ağaçlarının meyveleri yuvarlak, sarkık toplar biçimindedir ve kışın dağılarak tüylü tohumlar saçar. Bu tüylerin işlevi nedir?', 'Tohumların rüzgârla taşınması', ['Tohumların suda batması', 'Tohumların toprağa çakılması', 'Tohumların kuşlarca yenmesi'], 'Çınar meyve topu dağıldığında her küçük meyvenin tabanındaki tüyler paraşüt gibi davranır ve rüzgârla taşınmayı kolaylaştırır.'),
  ('Genç eğrelti yapraklarının topraktan çıkarken kıvrık, salyangoz kabuğu gibi sarmal bir biçimde olması ve sonra açılması dikkat çeker. Bu genç yaprakların hangi yararı olabilir?', 'Uçtaki büyüyen dokunun sarmalın içinde korunması', ['Böcekleri yakalayıp sindirmek', 'Kökleri topraktan çekmek', 'Tohumları içeride saklamak'], 'Sarmal hâldeki genç yaprakta büyüyen uç bölgesi iç kısımda kalır ve dış etkilerden korunur; yaprak büyüdükçe açılır.'),
  ('Çöllerde yağmurdan sonra birkaç hafta içinde çimlenip çiçek açan ve tohum bırakıp ölen bitkilerin bu stratejisi neye uyumdur?', 'Kısa süren nemli dönemi kullanmaya', ['Uzun ve yağışlı kışlara', 'Gölgeli orman tabanına', 'Tuzlu deniz suyuna'], 'Bu kısa ömürlü (efemer) bitkiler yaşamlarının çoğunu dayanıklı tohum olarak geçirir; yağış gelince hızla büyüyüp üreyerek kuraklığa yakalanmadan döngüyü tamamlar.'),
  ('Su altında tamamen batık yaşayan bitkilerin yapraklarında kütikulanın çok ince olması ya da hiç bulunmaması nasıl açıklanır?', 'Su kaybı riski olmadığından kalın kütikulaya gerek kalmaması', ['Bu bitkilerin hiç fotosentez yapmaması', 'Kütikulanın suda çözünmesi', 'Bu bitkilerin tamamen köksüz olması'], 'Kütikula karada su kaybını önlemek için gelişmiştir; su altında bu tehlike yoktur ve ince yüzey sudan gaz ve mineral alımını kolaylaştırır.'),
  ('Su mercimeği gibi küçük, yüzen su bitkilerinin bir göl yüzeyini kısa sürede kaplayabilmesi en çok hangi üreme yoluyla gerçekleşir?', 'Hızlı vejetatif çoğalma', ['Kozalakla çoğalma', 'Yalnızca tohumla çoğalma', 'Sporla çoğalma'], 'Su mercimekleri tomurcuklanma benzeri bir yolla ana bitkiden yeni bireyler ayırarak çok hızlı çoğalır.'),
  ('Sazlık ve bataklıklarda yetişen kamışların gövdelerinin içi boştur. Bu yapı bitkiye hangi yararı sağlar?', 'Hafiflik ve köklere hava iletimi', ['Gövdenin suyu depolaması', 'Böceklerin gövdede yaşaması', 'Tohumların gövdede saklanması'], 'İçi boş gövdeler hem hafif ve esnek olup rüzgârda kırılmayı azaltır hem de su altındaki kök ve rizomlara hava taşınmasına yardım eder.'),
  ('Deniz kıyısındaki kumullarda yetişen bitkilerin derin ve yaygın kök sistemleri geliştirmesinin en önemli nedeni nedir?', 'Hareketli kumda tutunmak ve derindeki suya ulaşmak', ['Kumdan yüksek miktarda azot almak', 'Fotosentezi köklerde yapmak', 'Tuzlu suyu yapraklara pompalamak'], 'Kum çabuk kurur ve rüzgârla yer değiştirir; derin ve yaygın kökler bitkiyi sabitler ve yüzeyin altındaki nemi kullanmasını sağlar.'),
  ('Bir tuz bataklığında yetişen bitkinin yapraklarının üzerinde zaman zaman beyaz kristaller görülüyor. Bu kristallerin en olası kaynağı nedir?', 'Bitkinin tuz bezleriyle dışarı attığı tuz', ['Yaprakta biriken şeker', 'Havadan düşen kar', 'Yaprağı yiyen böceklerin salgısı'], 'Bazı halofitler fazla tuzu yapraklarındaki özel bezlerle dışarı salgılar; su buharlaşınca tuz kristal olarak yüzeyde kalır.'),
  ('Bir bitkinin çiçekleri yalnızca ilkbaharın ilk haftalarında, ağaçlar yapraklanmadan önce açıyor. Bu bitki büyük olasılıkla nerede yaşar?', 'Yaprak döken bir ormanın tabanında', ['Tropikal yağmur ormanının tepe örtüsünde', 'Bir çölün ortasında', 'Denizin derinliklerinde'], 'Orman tabanı bitkileri ağaçlar yapraklanıp gölge oluşmadan önceki kısa aydınlık dönemi kullanarak büyür ve çiçeklenir.'),
  ('Toprağın pH değeri bitkilerin besin elementlerini alabilmesini etkiler. Çay ve ormangülü gibi bitkilerin en iyi yetiştiği toprak için hangisi doğrudur?', 'Asidik topraklar', ['Çok kireçli bazik topraklar', 'Tuzlu kumul toprakları', 'Saf kil topraklar'], 'Çay ve ormangülü asidik toprak bitkileridir; kireçli topraklarda demir gibi elementleri alamayıp yapraklarında sararma görülür.'),
  ('Anadolu\'da halk arasında \'ada çayı\' olarak bilinen bitkilerin çoğu hangi cinse aittir?', 'Salvia', ['Pinus', 'Quercus', 'Crocus'], 'Ada çayı olarak toplanan bitkilerin büyük kısmı ballıbabagillerden Salvia cinsindendir; Türkiye bu cinsin pek çok türüne ev sahipliği yapar.'),
  ('Sakız ve ardıç gibi bazı bitkilerin dallarından sızan reçine, gövdede hangi yapılarda üretilip taşınır?', 'Reçine kanallarında', ['Kök tüylerinde', 'Stomalarda', 'Polen keselerinde'], 'Kozalaklılar ve bazı kapalı tohumlular gövde ve yapraklarında reçine kanalları taşır; yaralanmada reçine bu kanallardan dışarı sızar.'),
  ('Kauçuk ağacından lateks toplanırken gövdeye eğik çizikler açılır ve akan süt bir kaba toplanır. Lateks bitkiye ne gibi bir yarar sağlıyor olabilir?', 'Yaraları kapatıp otçullara karşı korumak', ['Fotosentez için ışık toplamak', 'Tohumları rüzgârla dağıtmak', 'Kökleri topraktan çekmek'], 'Lateks yaralanınca hızla akıp pıhtılaşır; yarayı kapatır ve yapışkan, kötü tatlı yapısıyla böcek ve otçulları caydırır.'),
  ('Olgunlaşmamış meyvelerin genellikle yeşil, ekşi ve sert olması bitkiye nasıl bir yarar sağlar?', 'Tohum olgunlaşmadan meyvenin yenmesini engeller', ['Fotosentezi tamamen durdurur', 'Meyvenin rüzgârla uçmasını sağlar', 'Tohumların hemen çimlenmesini sağlar'], 'Olgunlaşmamış meyvenin göze çarpmaması ve tadının kötü olması, henüz çimlenemeyecek tohumların hayvanlarca taşınıp boşa gitmesini önler.'),
  ('Kesme çiçeklerin vazoda daha uzun süre dayanması için olgun meyvelerin yanına konmaması önerilir. Bunun nedeni nedir?', 'Meyvelerin saldığı etilen çiçeklerin solmasını hızlandırır', ['Meyveler çiçeklerin suyunu emer', 'Meyveler çiçekleri gölgede bırakır', 'Meyveler çiçeklere böcek taşır'], 'Etilen yalnızca olgunlaşmayı değil, çiçek ve yaprakların yaşlanmasını ve dökülmesini de hızlandırır.'),
  ('Uzun süre kuraklık yaşayan bir bitki tohumlarının dinlenme hâlinde kalmasını sağlayarak çimlenmeyi uygun zamana erteler. Tohum dinlenmesinin sürdürülmesinde başlıca rol oynayan hormon hangisidir?', 'Absisik asit', ['Etilen', 'Oksin', 'Sitokinin'], 'Absisik asit tohumlarda dormansiyi sürdürür ve çimlenmeyi baskılar; giberellin ise bu etkiye karşı çimlenmeyi uyarır.'),
  ('Elma, armut ve kiraz ağaçlarında farklı çeşitlerin bir arada dikilmesi çoğu zaman meyve verimini artırır. Bunun en önemli nedeni nedir?', 'Çeşitlerin birbirini tozlaştırması', ['Ağaçların birbirine gölge yapması', 'Köklerin birbirine azot vermesi', 'Ağaçların birbirinin yapraklarını dökmesi'], 'Bu meyvelerin birçok çeşidi kendi poleniyle iyi meyve bağlamaz; çiçeklenmesi uyumlu başka bir çeşit tozlaştırıcı olarak dikilir.'),
  ('Bal arılarının sayısının bir bölgede hızla azalması aşağıdaki tarım ürünlerinden en çok hangisinin verimini doğrudan düşürür?', 'Badem', ['Buğday', 'Mısır', 'Pirinç'], 'Badem çiçekleri böceklerle, özellikle arılarla tozlaşır; buğday, mısır ve pirinç ise rüzgârla tozlaşan tahıllardır.'),
  ('Bir öğrenci aynı türden iki fidenin birini her gün su, diğerini her gün tuzlu su ile suluyor. Birkaç gün sonra tuzlu suyla sulanan fidenin solduğunu görüyor. Bu deneyde bağımlı değişken hangisidir?', 'Fidenin solup solmaması', ['Sulama suyunun tuzluluğu', 'Fidenin türü', 'Saksıların büyüklüğü'], 'Araştırmacının değiştirdiği etken (tuzluluk) bağımsız değişkendir; buna bağlı olarak ölçülen sonuç, yani fidenin durumu, bağımlı değişkendir.'),
  ('Defne ağaçlarının bazılarının hiç meyve vermediği, bazılarının ise her yıl siyah meyveler oluşturduğu görülür. Bunun açıklaması hangisidir?', 'Defne iki evciklidir; meyveyi yalnızca dişi ağaçlar verir', ['Meyve veren ağaçlar başka bir türdür', 'Meyve vermeyen ağaçlar her zaman hastadır', 'Defne yalnızca on yılda bir meyve verir'], 'Defnede erkek ve dişi çiçekler ayrı bireylerde bulunur; erkek ağaçlar polen üretir ama meyve oluşturmaz.'),
  ('Bir dağda yetişen endemik bir bitkinin yalnızca 1800 metre ile 2200 metre arasında bulunduğu biliniyor. İklim ısındığında bu türün yayılışıyla ilgili en olası beklenti hangisidir?', 'Uygun kuşağın yukarı kayıp daralması', ['Türün ovalara yayılması', 'Türün yayılışının hiç değişmemesi', 'Türün deniz kıyısına inmesi'], 'Isınmayla birlikte uygun sıcaklık kuşağı daha yüksek rakımlara kayar; dağın tepesine yaklaşıldıkça alan daraldığından tür için yaşanabilir yer azalır.'),
  ('Zeytinyağı, ayçiçek yağı ve fındık yağı karşılaştırıldığında, zeytinyağının diğerlerinden farklı olarak bitkinin hangi kısmından elde edildiği söylenebilir?', 'Meyvenin etli kısmından', ['Tohumun çeneklerinden', 'Kökün depo dokusundan', 'Yaprakların mumlu yüzeyinden'], 'Zeytinyağı zeytin meyvesinin etli kısmı sıkılarak elde edilir; ayçiçek ve fındık yağı ise tohumun ya da çekirdek içinin yağca zengin dokularından çıkarılır.'),
];
